                    img { max-width: 100%; height: auto; display: block; margin: 20px auto; }
                    a { text-decoration: underline; color: #000; }

                    /* Nascondi header/footer di default del browser se possibile (supporto limitato) */
                    @page {
                        margin: 2cm;
                    }
                </style>
            </head>
            <body>
                <h1>${result.title}</h1>
                ${finalHtml}
            </body>
            </html>
        `;

        printWindow.document.write(htmlContent);
        printWindow.document.close();
        printWindow.focus();

        // Aspettiamo che le immagini (se presenti) si carichino prima di stampare
        setTimeout(() => {
            printWindow.print();
            printWindow.close();
        }, 500);
    };

    const handleImageMapChange = (index: number, value: string) => {
