const ImageGenerator: React.FC<{ keyPhrase: string; onImageGenerated: (url: string) => void }> = ({ keyPhrase, onImageGenerated }) => {
    const [prompt, setPrompt] = useState('');
    const [generatedImage, setGeneratedImage] = useState<string | null>(null);
    const [isGenerating, setIsGenerating] = useState(false);
    const [error, setError] = useState<string | null>(null);
    const [copied, setCopied] = useState(false);

    const handleGenerate = useCallback(async () => {
        if (!prompt.trim()) return;
        setIsGenerating(true);
        setError(null);
        setGeneratedImage(null);
        try {
            const imageData = await generateImage(prompt);
            const imageUrl = `data:image/jpeg;base64,${imageData}`;
            setGeneratedImage(imageUrl);
            onImageGenerated(imageUrl);
        } catch (e) {
            setError(e instanceof Error ? e.message : 'Errore generazione immagine.');
        } finally {
            setIsGenerating(false);
        }
    }, [prompt, onImageGenerated]);

    return (
        <div className="bg-slate-900/50 p-5 rounded-xl border border-slate-700/50">
            <div className="flex items-center gap-2 mb-4">
                <PhotoIcon className="w-5 h-5 text-indigo-400" />
                <h3 className="font-bold text-slate-200 uppercase tracking-tight text-sm">Laboratorio Immagini IA</h3>
            </div>
            <div className="flex flex-col gap-3">
                <div className="flex gap-2">
                    <input
                        type="text"
                        value={prompt}
                        onChange={(e) => setPrompt(e.target.value)}
                        placeholder="Descrivi l'immagine desiderata..."
                        className="flex-1 p-3 bg-slate-800 border border-slate-700 rounded-lg text-sm text-slate-300 focus:ring-1 focus:ring-indigo-500 outline-none"
                    />
                    <button 
                        onClick={handleGenerate} 
                        disabled={isGenerating}
                        className="bg-indigo-600 hover:bg-indigo-500 disabled:opacity-50 p-3 rounded-lg text-white transition-all shadow-lg shadow-indigo-600/20"
                    >
                        {isGenerating ? '...' : <SparklesIcon className="w-5 h-5" />}
                    </button>
                </div>
                {generatedImage && (
                    <div className="mt-4 animate-in fade-in duration-500">
                        <img src={generatedImage} alt="Generated" className="rounded-lg border border-slate-700 mb-3 w-full object-cover aspect-video" />
                        <button 
                            onClick={() => {
                                navigator.clipboard.writeText(`<img src="${generatedImage}" alt="${keyPhrase}" />`);
                                setCopied(true);
                                setTimeout(() => setCopied(false), 2000);
                            }}
                            className="w-full text-xs p-2 bg-slate-800 hover:bg-slate-700 text-slate-300 rounded border border-slate-700 transition-colors"
                        >
                            {copied ? 'Codice Copiato!' : 'Copia Codice HTML Immagine'}
                        </button>
                    </div>
                )}
            </div>
        </div>
    );
};

