import { GoogleGenAI, Type } from "@google/genai";
import { SeoResult, GroundingSource } from '../types';

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const responseSchema = {
    type: Type.OBJECT,
    properties: {
        keyPhrase: { type: Type.STRING },
        title: { type: Type.STRING },
        description: { type: Type.STRING },
        slug: { type: Type.STRING },
        htmlContent: { type: Type.STRING },
        tags: { type: Type.STRING },
        categories: { type: Type.STRING },
        socialMediaPost: { type: Type.STRING },
        seoChecklist: {
            type: Type.ARRAY,
            items: {
                type: Type.OBJECT,
                properties: {
                    item: { type: Type.STRING },
                    status: { type: Type.STRING },
                    details: { type: Type.STRING }
                },
                required: ["item", "status", "details"]
            }
        },
        readability: {
            type: Type.ARRAY,
            items: {
                type: Type.OBJECT,
                properties: {
                    criteria: { type: Type.STRING },
                    status: { type: Type.STRING },
                    score: { type: Type.STRING },
                    message: { type: Type.STRING }
                },
                required: ["criteria", "status", "score", "message"]
            }
        }
    },
    required: ["keyPhrase", "title", "description", "slug", "htmlContent", "tags", "categories", "seoChecklist", "socialMediaPost", "readability"],
};

export const optimizeArticleForSeo = async (articleText: string): Promise<SeoResult> => {
    try {
        const prompt = `Sei un Senior SEO Specialist & Content Strategist. Il tuo obiettivo è rendere questo articolo una "Pillar Page" imbattibile per i motori di ricerca.

**REGOLE DI OTTIMIZZAZIONE MASSIMA:**
1. **Lunghezza Ottimale SEO**: Punta a una lunghezza tra le 1000 e le 1500 parole. Se l'originale è breve, usa il tool "googleSearch" per approfondire i concetti, aggiungere paragrafi di contesto, statistiche e dati reali. Non aggiungere "fluff" (parole vuote), ma "sostanza informativa".
2. **E-E-A-T (Esperienza, Competenza, Autorevolezza, Fiducia)**: Arricchisci il testo con citazioni o riferimenti a fonti autorevoli trovate via web search.
3. **Indicizzabilità**: 
   - Usa la Focus Keyword nel primo 10% del testo.
   - Crea una struttura H1-H2-H3 gerarchica perfetta.
   - Inserisci varianti semantiche (LSI keywords) della frase chiave.
4. **HTML Pulito**: Genera HTML5 semantico. Inserisci <!-- IMAGE_PLACEHOLDER: descrizione --> nei punti dove un'immagine migliorerebbe il tempo di permanenza (Dwell Time).
5. **Checklist SEO**: Verifica Title (55-60 car), Meta Description (140-155 car), Slug (breve e con keyword).

**Articolo originale da trasformare:**
${articleText}`;

        const response = await ai.models.generateContent({
            model: "gemini-3-flash-preview",
            contents: prompt,
            config: {
                responseMimeType: "application/json",
                responseSchema: responseSchema,
                tools: [{ googleSearch: {} }],
                thinkingConfig: { thinkingBudget: 0 }
            },
        });

        const jsonText = response.text.trim();
        const result: SeoResult = JSON.parse(jsonText);

        const sources: GroundingSource[] = [];
        const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;
        if (chunks) {
            chunks.forEach((chunk: any) => {
                if (chunk.web?.uri) {
                    sources.push({
                        title: chunk.web.title || "Fonte esterna",
                        uri: chunk.web.uri
                    });
                }
            });
        }

        result.groundingSources = Array.from(new Map(sources.map(s => [s.uri, s])).values());

        return result;

    } catch (error) {
        console.error("Gemini Error:", error);
        throw new Error("Errore durante l'ottimizzazione SEO profonda.");
    }
};

export const generateImage = async (prompt: string): Promise<string> => {
    try {
        const response = await ai.models.generateImages({
            model: 'imagen-4.0-generate-001',
            prompt: `High-quality, professional blog post illustration: ${prompt}. Modern corporate style, clear, bright.`,
            config: {
              numberOfImages: 1,
              outputMimeType: 'image/jpeg',
              aspectRatio: '16:9',
            },
        });

        if (response.generatedImages?.[0]) {
            return response.generatedImages[0].image.imageBytes;
        }
        throw new Error("Immagine non generata.");
    } catch (error) {
        throw new Error("Errore generazione immagine.");
    }
};

