import { GoogleGenAI, Type } from "@google/genai";
import { SeoResult, GroundingSource } from '../types';

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const responseSchema = {
    type: Type.OBJECT,
    properties: {
        keyPhrase: { type: Type.STRING },
        title: { type: Type.STRING },
        description: { type: Type.STRING },
        slug: { type: Type.STRING },
        htmlContent: { type: Type.STRING },
        tags: { type: Type.STRING },
        categories: { type: Type.STRING },
        socialMediaPost: { type: Type.STRING },
        seoChecklist: {
            type: Type.ARRAY,
            items: {
                type: Type.OBJECT,
                properties: {
                    item: { type: Type.STRING },
                    status: { type: Type.STRING },
                    details: { type: Type.STRING }
                },
                required: ["item", "status", "details"]
            }
        },
        readability: {
            type: Type.ARRAY,
            items: {
                type: Type.OBJECT,
                properties: {
                    criteria: { type: Type.STRING },
                    status: { type: Type.STRING },
                    score: { type: Type.STRING },
                    message: { type: Type.STRING }
                },
                required: ["criteria", "status", "score", "message"]
            }
        }
    },
    required: ["keyPhrase", "title", "description", "slug", "htmlContent", "tags", "categories", "seoChecklist", "socialMediaPost", "readability"],
};

export const optimizeArticleForSeo = async (articleText: string): Promise<SeoResult> => {
    try {
        const prompt = `Sei un Senior SEO Specialist. Trasforma questo testo in un articolo Pillar (1000-1500 parole).
Usa Google Search per trovare dati reali e citazioni. Struttura in HTML5 semantico.
Articolo: ${articleText}`;

        const response = await ai.models.generateContent({
            model: "gemini-3-flash-preview",
            contents: prompt,
            config: {
                responseMimeType: "application/json",
                responseSchema: responseSchema,
                tools: [{ googleSearch: {} }],
            },
        });

        const jsonText = response.text.trim();
        const result: SeoResult = JSON.parse(jsonText);
        result.groundingSources = extractSources(response);
        return result;
    } catch (error) {
        throw new Error("Errore durante l'ottimizzazione SEO.");
    }
};

export const enrichArticleDepth = async (currentResult: SeoResult, originalText: string): Promise<SeoResult> => {
    try {
        const prompt = `L'articolo attuale sulla keyword "${currentResult.keyPhrase}" è troppo breve per gli standard SEO competitivi.

**MISSIONE**:
1. Usa Google Search per trovare 3-4 sotto-argomenti avanzati, casi studio o statistiche recenti NON ancora presenti nel testo.
2. Espandi l'HTML esistente aggiungendo nuove sezioni (H2/H3) e paragrafi dettagliati.
3. Mantieni lo stile professionale e l'HTML pulito.
4. L'obiettivo finale è superare le 1200 parole di puro valore.

**CONTENUTO ATTUALE**:
${currentResult.htmlContent}

**TESTO ORIGINALE DI RIFERIMENTO**:
${originalText}`;

        const response = await ai.models.generateContent({
            model: "gemini-3-flash-preview",
            contents: prompt,
            config: {
                responseMimeType: "application/json",
                responseSchema: responseSchema,
                tools: [{ googleSearch: {} }],
            },
        });

        const jsonText = response.text.trim();
        const result: SeoResult = JSON.parse(jsonText);

        // Uniamo le fonti vecchie con le nuove
        const newSources = extractSources(response);
        const allSources = [...(currentResult.groundingSources || []), ...newSources];
        result.groundingSources = Array.from(new Map(allSources.map(s => [s.uri, s])).values());

        return result;
    } catch (error) {
        throw new Error("Errore durante l'arricchimento del contenuto.");
    }
};

const extractSources = (response: any): GroundingSource[] => {
    const sources: GroundingSource[] = [];
    const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;
    if (chunks) {
        chunks.forEach((chunk: any) => {
            if (chunk.web?.uri) {
                sources.push({
                    title: chunk.web.title || "Fonte esterna",
                    uri: chunk.web.uri
                });
            }
        });
    }
    return Array.from(new Map(sources.map(s => [s.uri, s])).values());
};

export const generateImage = async (prompt: string): Promise<string> => {
    try {
        const response = await ai.models.generateImages({
            model: 'imagen-4.0-generate-001',
            prompt: `High-quality blog image: ${prompt}`,
            config: { numberOfImages: 1, outputMimeType: 'image/jpeg', aspectRatio: '16:9' },
        });
        return response.generatedImages?.[0]?.image.imageBytes || "";
    } catch (error) { return ""; }
};

import React, { useState, useCallback, useEffect, useRef } from 'react';
import { ArticleInput } from './components/ArticleInput';
import { SeoOutput } from './components/SeoOutput';
import { optimizeArticleForSeo, enrichArticleDepth } from './services/geminiService';
import { SeoResult, SavedSeoResult } from './types';
import { SparklesIcon } from './components/IconComponents';
import { LoadModal } from './components/LoadModal';

const App: React.FC = () => {
    const [articleText, setArticleText] = useState<string>('');
    const [seoResult, setSeoResult] = useState<SeoResult | null>(null);
    const [isLoading, setIsLoading] = useState<boolean>(false);
    const [isEnriching, setIsEnriching] = useState<boolean>(false);
    const [error, setError] = useState<string | null>(null);
    const [savedArticles, setSavedArticles] = useState<SavedSeoResult[]>([]);
    const [isLoadModalOpen, setIsLoadModalOpen] = useState(false);
    const [lastAutoSave, setLastAutoSave] = useState<Date | null>(null);

    const STORAGE_KEY = 'seo-optimizer-saved-articles';
    const AUTOSAVE_KEY = 'cosmonet-autosave-draft';
    const articleTextRef = useRef(articleText);

    useEffect(() => { articleTextRef.current = articleText; }, [articleText]);

    useEffect(() => {
        try {
            const storedArticles = localStorage.getItem(STORAGE_KEY);
            if (storedArticles) setSavedArticles(JSON.parse(storedArticles));
            const autoSavedDraft = localStorage.getItem(AUTOSAVE_KEY);
            if (autoSavedDraft) {
                setArticleText(autoSavedDraft);
                setLastAutoSave(new Date());
            }
        } catch (error) { localStorage.removeItem(STORAGE_KEY); }
    }, []);

    useEffect(() => {
        const intervalId = setInterval(() => {
            const currentText = articleTextRef.current;
            if (currentText?.trim()) {
                localStorage.setItem(AUTOSAVE_KEY, currentText);
                setLastAutoSave(new Date());
            }
        }, 120000);
        return () => clearInterval(intervalId);
    }, []);

    const handleOptimize = useCallback(async () => {
        if (!articleText.trim()) {
            setError('Inserisci il testo dell\'articolo.');
            return;
        }
        setIsLoading(true);
        setError(null);
        try {
            const result = await optimizeArticleForSeo(articleText);
            setSeoResult(result);
        } catch (e) {
            setError(e instanceof Error ? e.message : 'Errore inaspettato.');
        } finally {
            setIsLoading(false);
        }
    }, [articleText]);

    const handleIncreaseDepth = useCallback(async () => {
        if (!seoResult) return;
        setIsEnriching(true);
        setError(null);
        try {
            const enriched = await enrichArticleDepth(seoResult, articleText);
            setSeoResult(enriched);
        } catch (e) {
            setError("Impossibile arricchire l'articolo. Riprova.");
        } finally {
            setIsEnriching(false);
        }
    }, [seoResult, articleText]);

    const handleSaveArticle = useCallback((finalHtml?: string) => {
        if (!seoResult) return;
        const newSavedArticle: SavedSeoResult = {
            ...seoResult,
            htmlContent: finalHtml || seoResult.htmlContent,
            id: Date.now().toString(),
            originalArticleText: articleText,
        };
        const updatedArticles = [...savedArticles, newSavedArticle];
        setSavedArticles(updatedArticles);
        localStorage.setItem(STORAGE_KEY, JSON.stringify(updatedArticles));
    }, [seoResult, articleText, savedArticles]);

    const handleLoadArticle = useCallback((article: SavedSeoResult) => {
        setArticleText(article.originalArticleText);
        const { id, originalArticleText, ...resultData } = article;
        setSeoResult(resultData);
        setIsLoadModalOpen(false);
        setError(null);
    }, []);

    const handleDeleteArticle = useCallback((articleId: string) => {
        const updatedArticles = savedArticles.filter(a => a.id !== articleId);
        setSavedArticles(updatedArticles);
        localStorage.setItem(STORAGE_KEY, JSON.stringify(updatedArticles));
    }, [savedArticles]);

    return (
        <div className="bg-slate-900 min-h-screen text-slate-200 font-sans">
            <div className="container mx-auto p-4 md:p-8">
                <header className="text-center mb-8 md:mb-12">
                    <div className="flex items-center justify-center gap-3">
                        <SparklesIcon className="w-10 h-10 text-indigo-400" />
                        <h1 className="text-4xl md:text-5xl font-bold bg-gradient-to-r from-indigo-400 to-cyan-400 text-transparent bg-clip-text">
                            CosmoNet_Articoli_Perfetti
                        </h1>
                    </div>
                </header>

                <main className="grid grid-cols-1 lg:grid-cols-2 gap-8">
                    <ArticleInput
                        value={articleText}
                        onChange={setArticleText}
                        onOptimize={handleOptimize}
                        isLoading={isLoading || isEnriching}
                        onLoadClick={() => setIsLoadModalOpen(true)}
                        savedCount={savedArticles.length}
                        lastAutoSave={lastAutoSave}
                        onExportDB={() => {}}
                        onImportDB={() => {}}
                    />
                    <SeoOutput
                        result={seoResult}
                        isLoading={isLoading}
                        isEnriching={isEnriching}
                        onIncreaseDepth={handleIncreaseDepth}
                        error={error}
                        onSave={handleSaveArticle}
                    />
                </main>
            </div>
            <LoadModal
                isOpen={isLoadModalOpen}
                onClose={() => setIsLoadModalOpen(false)}
                articles={savedArticles}
                onLoad={handleLoadArticle}
                onDelete={handleDeleteArticle}
            />
        </div>
    );
};

export default App;

