import { GoogleGenAI, Type } from "@google/genai";
import { SeoResult, GroundingSource } from '../types';

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const responseSchema = {
    type: Type.OBJECT,
    properties: {
        keyPhrase: { type: Type.STRING },
        title: { type: Type.STRING },
        description: { type: Type.STRING },
        slug: { type: Type.STRING },
        htmlContent: { type: Type.STRING },
        tags: { type: Type.STRING },
        categories: { type: Type.STRING },
        socialMediaPost: { type: Type.STRING },
        seoChecklist: {
            type: Type.ARRAY,
            items: {
                type: Type.OBJECT,
                properties: {
                    item: { type: Type.STRING },
                    status: { type: Type.STRING },
                    details: { type: Type.STRING }
                },
                required: ["item", "status", "details"]
            }
        },
        readability: {
            type: Type.ARRAY,
            items: {
                type: Type.OBJECT,
                properties: {
                    criteria: { type: Type.STRING },
                    status: { type: Type.STRING },
                    score: { type: Type.STRING },
                    message: { type: Type.STRING }
                },
                required: ["criteria", "status", "score", "message"]
            }
        }
    },
    required: ["keyPhrase", "title", "description", "slug", "htmlContent", "tags", "categories", "seoChecklist", "socialMediaPost", "readability"],
};

export const optimizeArticleForSeo = async (articleText: string): Promise<SeoResult> => {
    try {
        const prompt = `Sei un Senior Content Engineer & SEO Expert. Trasforma questo testo in un articolo Pillar (1000-1500 parole) pronto per la prima pagina di Google.

**REGOLE MANDATORIE PER I LINK:**
1. **Ricerca Link Ufficiali**: Usa Google Search per trovare le pagine ufficiali, le documentazioni e le pagine di download di ogni prodotto, software o servizio menzionato (es. se parli di "Google Labs", trova il link a labs.google).
2. **Incorporamento Contestuale**: Inserisci i link direttamente nel testo HTML usando tag <a href="..." target="_blank" rel="noopener noreferrer">. 
3. **Download e Pagine Ufficiali**: Dai priorità a link che portano a "Download", "Sito Ufficiale" o "Risorse Progetto".
4. **Nessuna Bibliografia**: NON inserire una lista di "Fonti" o "Riferimenti" in fondo all'articolo. I link devono essere fluidi e naturali all'interno dei paragrafi.
5. **Struttura**: HTML5 semantico (H2, H3, p, strong, ul/li).

Articolo da ottimizzare:
${articleText}`;

        const response = await ai.models.generateContent({
            model: "gemini-3-flash-preview",
            contents: prompt,
            config: {
                responseMimeType: "application/json",
                responseSchema: responseSchema,
                tools: [{ googleSearch: {} }],
            },
        });

        const jsonText = response.text.trim();
        const result: SeoResult = JSON.parse(jsonText);
        result.groundingSources = extractSources(response);
        return result;
    } catch (error) {
        throw new Error("Errore durante l'ottimizzazione SEO.");
    }
};

export const enrichArticleDepth = async (currentResult: SeoResult, originalText: string): Promise<SeoResult> => {
    try {
        const prompt = `Espandi l'articolo attuale per renderlo ancora più autorevole (E-E-A-T).

**MISSIONE ARRICCHIMENTO:**
1. **Ricerca Avanzata**: Usa Google Search per trovare link diretti a risorse ufficiali, guide tecniche e pagine di download relative all'argomento "${currentResult.keyPhrase}".
2. **Integrazione Link**: Inserisci nuovi paragrafi o sezioni (H2/H3) che incorporino link cliccabili ai siti ufficiali citati. 
3. **Niente link a fonti generiche**: Non voglio una lista di siti di news, ma solo link alle "Case Madri" o risorse tecniche dirette.
4. **Volume**: Aggiungi circa 300-500 parole di contenuto tecnico di alta qualità.

**CONTENUTO ATTUALE**:
${currentResult.htmlContent}`;

        const response = await ai.models.generateContent({
            model: "gemini-3-flash-preview",
            contents: prompt,
            config: {
                responseMimeType: "application/json",
                responseSchema: responseSchema,
                tools: [{ googleSearch: {} }],
            },
        });

        const jsonText = response.text.trim();
        const result: SeoResult = JSON.parse(jsonText);

        const newSources = extractSources(response);
        const allSources = [...(currentResult.groundingSources || []), ...newSources];
        result.groundingSources = Array.from(new Map(allSources.map(s => [s.uri, s])).values());

        return result;
    } catch (error) {
        throw new Error("Errore durante l'arricchimento del contenuto.");
    }
};

const extractSources = (response: any): GroundingSource[] => {
    const sources: GroundingSource[] = [];
    const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;
    if (chunks) {
        chunks.forEach((chunk: any) => {
            if (chunk.web?.uri) {
                sources.push({
                    title: chunk.web.title || "Fonte esterna",
                    uri: chunk.web.uri
                });
            }
        });
    }
    return Array.from(new Map(sources.map(s => [s.uri, s])).values());
};

export const generateImage = async (prompt: string): Promise<string> => {
    try {
        const response = await ai.models.generateImages({
            model: 'imagen-4.0-generate-001',
            prompt: `Professional technology illustration: ${prompt}`,
            config: { numberOfImages: 1, outputMimeType: 'image/jpeg', aspectRatio: '16:9' },
        });
        return response.generatedImages?.[0]?.image.imageBytes || "";
    } catch (error) { return ""; }
};

