};

export const optimizeArticleForSeo = async (articleText: string): Promise<SeoResult> => {
    try {
        const prompt = `Sei un Senior Content Engineer & SEO Expert specializzato in blog professionali.

**OBIETTIVO**: Trasforma il testo fornito in un articolo Pillar (1200+ parole) ottimizzato per Google.

**REGOLE CRITICHE**:
1. **Tassonomia Blog**: Genera 3-5 TAG pertinenti (separati da virgola) e 1-2 CATEGORIE professionali.
2. **Ricerca Link Ufficiali**: Usa Google Search per trovare link alle pagine ufficiali, documentazioni e download dei software/servizi citati.
3. **Link nel Testo**: Inserisci i link direttamente nell'HTML usando <a href="..." target="_blank">. Non fare liste di fonti a fine articolo.
4. **Struttura HTML**: Usa tag semantici (H1, H2, H3, strong, ul).
5. **SEO Meta**: Crea Title, Meta Description e Slug perfetti.

Articolo da processare:
${articleText}`;

        const response = await ai.models.generateContent({
            model: "gemini-3-flash-preview",
            contents: prompt,
            config: {
                responseMimeType: "application/json",
                responseSchema: responseSchema,
                tools: [{ googleSearch: {} }],
            },
        });

        const jsonText = response.text.trim();
        const result: SeoResult = JSON.parse(jsonText);
        result.groundingSources = extractSources(response);
        return result;
    } catch (error) {
        throw new Error("Errore durante l'ottimizzazione SEO.");
    }
};

export const enrichArticleDepth = async (currentResult: SeoResult, originalText: string): Promise<SeoResult> => {
    try {
        const prompt = `Espandi l'articolo per raggiungere la massima profondità SEO (E-E-A-T).

**ISTRUZIONI DI ESPANSIONE**:
1. **Nuove Sezioni**: Aggiungi paragrafi tecnici, casi d'uso o approfondimenti trovati via Google Search.
2. **Link di Download**: Cerca attivamente link ufficiali di download o documentazione per i termini citati.
3. **Mantenimento Tassonomia**: Verifica e migliora Tag e Categorie se necessario.
4. **Link Integrati**: Incorpora i link ufficiali nel nuovo testo HTML.

**CONTENUTO ATTUALE**:
${currentResult.htmlContent}`;

        const response = await ai.models.generateContent({
            model: "gemini-3-flash-preview",
            contents: prompt,
            config: {
                responseMimeType: "application/json",
                responseSchema: responseSchema,
                tools: [{ googleSearch: {} }],
            },
        });

        const jsonText = response.text.trim();
        const result: SeoResult = JSON.parse(jsonText);

        const newSources = extractSources(response);
        const allSources = [...(currentResult.groundingSources || []), ...newSources];
        result.groundingSources = Array.from(new Map(allSources.map(s => [s.uri, s])).values());

        return result;
    } catch (error) {
        throw new Error("Errore durante l'arricchimento.");
    }
};

const extractSources = (response: any): GroundingSource[] => {
    const sources: GroundingSource[] = [];
    const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;
    if (chunks) {
        chunks.forEach((chunk: any) => {
            if (chunk.web?.uri) {
                sources.push({
                    title: chunk.web.title || "Fonte esterna",
                    uri: chunk.web.uri
                });
            }
        });
    }
    return Array.from(new Map(sources.map(s => [s.uri, s])).values());
};

export const generateImage = async (prompt: string): Promise<string> => {
    try {
        const response = await ai.models.generateImages({
            model: 'imagen-4.0-generate-001',
            prompt: `Professional blog illustration: ${prompt}`,
            config: { numberOfImages: 1, outputMimeType: 'image/jpeg', aspectRatio: '16:9' },
        });
        return response.generatedImages?.[0]?.image.imageBytes || "";
    } catch (error) { return ""; }
};

