import { GoogleGenAI, Type } from "@google/genai";
import { SeoResult, GroundingSource } from '../types';

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const responseSchema = {
    type: Type.OBJECT,
    properties: {
        keyPhrase: { type: Type.STRING },
        title: { type: Type.STRING },
        description: { type: Type.STRING },
        slug: { type: Type.STRING },
        htmlContent: { type: Type.STRING },
        tags: { type: Type.STRING },
        categories: { type: Type.STRING },
        socialMediaPost: { type: Type.STRING },
        seoChecklist: {
            type: Type.ARRAY,
            items: {
                type: Type.OBJECT,
                properties: {
                    item: { type: Type.STRING },
                    status: { type: Type.STRING },
                    details: { type: Type.STRING }
                },
                required: ["item", "status", "details"]
            }
        },
        readability: {
            type: Type.ARRAY,
            items: {
                type: Type.OBJECT,
                properties: {
                    criteria: { type: Type.STRING },
                    status: { type: Type.STRING },
                    score: { type: Type.STRING },
                    message: { type: Type.STRING }
                },
                required: ["criteria", "status", "score", "message"]
            }
        }
    },
    required: ["keyPhrase", "title", "description", "slug", "htmlContent", "tags", "categories", "seoChecklist", "socialMediaPost", "readability"],
};

export const optimizeArticleForSeo = async (articleText: string): Promise<SeoResult> => {
    try {
        const prompt = `Agisci come un Senior Content Strategist e SEO Auditor di una testata giornalistica tecnologica di alto livello.

**MISSIONE**: Trasforma l'input in un articolo Pillar (1200-1500 parole) iper-specializzato.

**TASSONOMIA (ESTREMAMENTE IMPORTANTE)**:
1. **CATEGORIE (3-5 specifiche)**: Non usare categorie generiche come "Tech" o "Blog". Identifica i cluster tematici esatti (es. "Intelligenza Artificiale Generativa", "Sviluppo Web Frontend", "Tool di Produttività Digitale").
2. **TAG SEO (15-20 tag iper-pertinenti)**: 
   - Genera una lista di tag che includano: entità nominate, software citati, keyword a coda lunga (long-tail) e termini tecnici.
   - Esempio: Se l'articolo parla di Google Labs, i tag devono essere: "Google Labs", "IA Generativa", "Beta Testing Google", "Innovazione AI", "Search Labs", ecc.
   - Devono essere separati SOLO da virgola e spazio (es: tag1, tag2, tag3).
   - EVITA CATEGORIE COME TAG. I tag devono essere specifici del contenuto.

**RICERCA E LINK (MANDATORIO)**:
- Usa Google Search per trovare i link ufficiali (home page) e le pagine di download di ogni servizio citato.
- Inserisci i link nel testo HTML: <a href="URL_UFFICIALE" target="_blank" rel="noopener noreferrer">Nome Prodotto</a>.
- Focalizzati solo su download ufficiali e documentazione tecnica. NON mettere link a siti di news generiche.

**STRUTTURA HTML**:
- Titoli H2 e H3 ricchi di keyword.
- Contenuto approfondito, tecnico e di valore (E-E-A-T).
- Niente bibliografia finale. I link devono essere nel corpo del testo.

Articolo da processare:
${articleText}`;

        const response = await ai.models.generateContent({
            model: "gemini-3-flash-preview",
            contents: prompt,
            config: {
                responseMimeType: "application/json",
                responseSchema: responseSchema,
                tools: [{ googleSearch: {} }],
            },
        });

        const jsonText = response.text.trim();
        const result: SeoResult = JSON.parse(jsonText);
        result.groundingSources = extractSources(response);
        return result;
    } catch (error) {
        throw new Error("Errore durante l'ottimizzazione SEO. L'IA potrebbe essere satura, riprova tra poco.");
    }
};

export const enrichArticleDepth = async (currentResult: SeoResult, originalText: string): Promise<SeoResult> => {
    try {
        const prompt = `Arricchisci questo articolo aumentandone la pertinenza tecnica e la densità di link ufficiali.

**ISTRUZIONI**:
1. **Espansione Tecnica**: Aggiungi almeno 400 parole di dettagli tecnici estratti via Google Search.
2. **Link di Download**: Trova e inserisci i link diretti per il download o la prova dei servizi menzionati.
3. **Miglioramento Tag**: Rivedi la lista dei tag attuale e aggiungine altri 5 ancora più specifici basati sulle nuove informazioni.
4. **Link contestuali**: Inserisci i link direttamente nell'HTML.

**CONTENUTO ATTUALE**:
${currentResult.htmlContent}`;

        const response = await ai.models.generateContent({
            model: "gemini-3-flash-preview",
            contents: prompt,
            config: {
                responseMimeType: "application/json",
                responseSchema: responseSchema,
                tools: [{ googleSearch: {} }],
            },
        });

        const jsonText = response.text.trim();
        const result: SeoResult = JSON.parse(jsonText);

        const newSources = extractSources(response);
        const allSources = [...(currentResult.groundingSources || []), ...newSources];
        result.groundingSources = Array.from(new Map(allSources.map(s => [s.uri, s])).values());

        return result;
    } catch (error) {
        throw new Error("Errore durante l'arricchimento.");
    }
};

const extractSources = (response: any): GroundingSource[] => {
    const sources: GroundingSource[] = [];
    const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;
    if (chunks) {
        chunks.forEach((chunk: any) => {
            if (chunk.web?.uri) {
                sources.push({
                    title: chunk.web.title || "Fonte ufficiale",
                    uri: chunk.web.uri
                });
            }
        });
    }
    return Array.from(new Map(sources.map(s => [s.uri, s])).values());
};

export const generateImage = async (prompt: string): Promise<string> => {
    try {
        const response = await ai.models.generateImages({
            model: 'imagen-4.0-generate-001',
            prompt: `Professional high-end technology editorial illustration: ${prompt}`,
            config: { numberOfImages: 1, outputMimeType: 'image/jpeg', aspectRatio: '16:9' },
        });
        return response.generatedImages?.[0]?.image.imageBytes || "";
    } catch (error) { return ""; }
};

