import { GoogleGenAI, Type } from "@google/genai";
import { SeoResult, GroundingSource } from '../types';

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const responseSchema = {
    type: Type.OBJECT,
    properties: {
        keyPhrase: { type: Type.STRING },
        title: { type: Type.STRING },
        description: { type: Type.STRING },
        slug: { type: Type.STRING },
        htmlContent: { type: Type.STRING },
        tags: { type: Type.STRING },
        categories: { type: Type.STRING },
        socialMediaPost: { type: Type.STRING },
        seoChecklist: {
            type: Type.ARRAY,
            items: {
                type: Type.OBJECT,
                properties: {
                    item: { type: Type.STRING },
                    status: { type: Type.STRING },
                    details: { type: Type.STRING }
                },
                required: ["item", "status", "details"]
            }
        },
        readability: {
            type: Type.ARRAY,
            items: {
                type: Type.OBJECT,
                properties: {
                    criteria: { type: Type.STRING },
                    status: { type: Type.STRING },
                    score: { type: Type.STRING },
                    message: { type: Type.STRING }
                },
                required: ["criteria", "status", "score", "message"]
            }
        }
    },
    required: ["keyPhrase", "title", "description", "slug", "htmlContent", "tags", "categories", "seoChecklist", "socialMediaPost", "readability"],
};

export const optimizeArticleForSeo = async (articleText: string): Promise<SeoResult> => {
    try {
        const prompt = `Agisci come Direttore Editoriale e Senior SEO Architect. Il tuo compito è trasformare l'input in un articolo Pillar definitivo, esaustivo e iper-approfondito.

**REGOLE DI CONTENUTO (ESSENZIALI)**:
1. **NESSUN LIMITE DI LUNGHEZZA**: Non limitarti a un numero di parole. Scrivi quanto necessario per essere ESAUSTIVO. L'articolo deve includere OGNI singola notizia, dato, o dettaglio fornito nell'input.
2. **ESPANSIOINE INTELLIGENTE**: Usa Google Search per approfondire i concetti citati, trovare specifiche tecniche mancanti e link ufficiali di riferimento o download.
3. **LETTURA FLUIDA**: Il tono deve essere professionale ma estremamente scorrevole. Evita muri di testo; usa paragrafi brevi, elenchi puntati e tag HTML semantici (H2, H3, strong).
4. **LINK CONTESTUALI**: Integra link ufficiali (<a href="..." target="_blank">) direttamente nel testo dove sono citati prodotti o servizi.

**ARCHITETTURA E TASSONOMIA (RILEVANZA MASSIMA)**:
1. **TAG SEO (15-20 tag)**: Genera tag iper-pertinenti. Devono essere "long-tail keywords" (es. "ottimizzazione motore di ricerca" invece di "SEO"). Devono essere separati SOLO da virgola e spazio.
2. **CATEGORIE (3-5 specifiche)**: Definisci categorie gerarchiche precise per un'architettura blog professionale.
3. **META-DATI**: Crea un Title e una Meta Description che massimizzino il CTR.

Testo sorgente da elaborare:
${articleText}`;

        const response = await ai.models.generateContent({
            model: "gemini-3-flash-preview",
            contents: prompt,
            config: {
                responseMimeType: "application/json",
                responseSchema: responseSchema,
                tools: [{ googleSearch: {} }],
            },
        });

        const jsonText = response.text.trim();
        const result: SeoResult = JSON.parse(jsonText);
        result.groundingSources = extractSources(response);
        return result;
    } catch (error) {
        console.error(error);
        throw new Error("Errore durante l'ottimizzazione SEO. L'IA ha riscontrato un problema nel processare l'esaustività richiesta.");
    }
};

export const enrichArticleDepth = async (currentResult: SeoResult, originalText: string): Promise<SeoResult> => {
    try {
        const prompt = `Analizza l'articolo attuale e portalo al livello successivo di profondità.

**MISSIONE**:
1. Trova nuovi angoli di approfondimento, casi studio o dati tecnici tramite Google Search.
2. Espandi l'HTML aggiungendo nuove sezioni (H2/H3).
3. Assicurati che ogni nuovo link trovato sia un link ufficiale o di download sicuro.
4. Mantieni la fluidità narrativa: non deve sembrare un'aggiunta forzata, ma un'evoluzione naturale del testo.

**CONTENUTO DA ESPANDERE**:
${currentResult.htmlContent}`;

        const response = await ai.models.generateContent({
            model: "gemini-3-flash-preview",
            contents: prompt,
            config: {
                responseMimeType: "application/json",
                responseSchema: responseSchema,
                tools: [{ googleSearch: {} }],
            },
        });

        const jsonText = response.text.trim();
        const result: SeoResult = JSON.parse(jsonText);

        const newSources = extractSources(response);
        const allSources = [...(currentResult.groundingSources || []), ...newSources];
        result.groundingSources = Array.from(new Map(allSources.map(s => [s.uri, s])).values());

        return result;
    } catch (error) {
        throw new Error("Errore durante l'arricchimento del contenuto.");
    }
};

const extractSources = (response: any): GroundingSource[] => {
    const sources: GroundingSource[] = [];
    const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;
    if (chunks) {
        chunks.forEach((chunk: any) => {
            if (chunk.web?.uri) {
                sources.push({
                    title: chunk.web.title || "Fonte Ufficiale",
                    uri: chunk.web.uri
                });
            }
        });
    }
    return Array.from(new Map(sources.map(s => [s.uri, s])).values());
};

export const generateImage = async (prompt: string): Promise<string> => {
    try {
        const response = await ai.models.generateImages({
            model: 'imagen-4.0-generate-001',
            prompt: `High-end editorial blog cover, professional lighting, style: tech-modern: ${prompt}`,
            config: { numberOfImages: 1, outputMimeType: 'image/jpeg', aspectRatio: '16:9' },
        });
        return response.generatedImages?.[0]?.image.imageBytes || "";
    } catch (error) { return ""; }
};

