import { GoogleGenAI, Type } from "@google/genai";
import { SeoResult, GroundingSource } from '../types';

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const responseSchema = {
    type: Type.OBJECT,
    properties: {
        keyPhrase: { type: Type.STRING },
        title: { type: Type.STRING },
        description: { type: Type.STRING },
        slug: { type: Type.STRING },
        htmlContent: { type: Type.STRING },
        tags: { type: Type.STRING },
        categories: { type: Type.STRING },
        socialMediaPost: { type: Type.STRING },
        seoChecklist: {
            type: Type.ARRAY,
            items: {
                type: Type.OBJECT,
                properties: {
                    item: { type: Type.STRING },
                    status: { type: Type.STRING },
                    details: { type: Type.STRING }
                },
                required: ["item", "status", "details"]
            }
        },
        readability: {
            type: Type.ARRAY,
            items: {
                type: Type.OBJECT,
                properties: {
                    criteria: { type: Type.STRING },
                    status: { type: Type.STRING },
                    score: { type: Type.STRING },
                    message: { type: Type.STRING }
                },
                required: ["criteria", "status", "score", "message"]
            }
        }
    },
    required: ["keyPhrase", "title", "description", "slug", "htmlContent", "tags", "categories", "seoChecklist", "socialMediaPost", "readability"],
};

export const optimizeArticleForSeo = async (articleText: string): Promise<SeoResult> => {
    try {
        const prompt = `Agisci come un Senior Editor e SEO Specialist. Il tuo compito è formattare e ottimizzare il testo fornito in un articolo professionale senza omettere alcuna informazione.

**REGOLE MANDATORIE (INTEGRITÀ DEL CONTENUTO)**:
1. **NON TAGLIARE NULLA**: Devi includere OGNI singola notizia, dato, statistica, nome o dettaglio presente nel testo originale. Non riassumere se questo comporta la perdita di informazioni.
2. **MANTIENI LA LUNGHEZZA**: L'articolo finale deve riflettere la profondità dell'input. Se l'input è lungo e dettagliato, l'output deve essere altrettanto lungo e dettagliato.
3. **STRUTTURA HTML SEMANTICA**: Usa tag HTML5 (H1, H2, H3, p, strong, ul, li) per rendere il testo leggibile e scansionabile dai motori di ricerca.
4. **FLUIDITÀ E SCORREVOLEZZA**: Trasforma il testo (anche se in forma di appunti o dati grezzi) in un articolo coerente e piacevole da leggere, mantenendo un tono professionale.

**SEO E TASSONOMIA**:
- **Tag SEO (15-20)**: Genera tag iper-specifici (long-tail) basati sulle entità e sui concetti trattati. Separali con virgola e spazio.
- **Categorie (3-5)**: Identifica le categorie editoriali esatte.
- **Link**: Se trovi riferimenti a prodotti o servizi, usa Google Search solo per recuperare i link ufficiali e inseriscili contestualmente nel testo HTML.

Testo sorgente da elaborare:
${articleText}`;

        const response = await ai.models.generateContent({
            model: "gemini-3-flash-preview",
            contents: prompt,
            config: {
                responseMimeType: "application/json",
                responseSchema: responseSchema,
                tools: [{ googleSearch: {} }],
            },
        });

        const jsonText = response.text.trim();
        const result: SeoResult = JSON.parse(jsonText);
        result.groundingSources = extractSources(response);
        return result;
    } catch (error) {
        console.error(error);
        throw new Error("Errore durante l'elaborazione. L'articolo è troppo complesso o l'IA ha riscontrato un problema.");
    }
};

export const enrichArticleDepth = async (currentResult: SeoResult, originalText: string): Promise<SeoResult> => {
    try {
        const prompt = `Prendi questo articolo e aggiungi ulteriori dettagli tecnici, link di download ufficiali e approfondimenti trovati sul web, assicurandoti di non rimuovere nulla di quanto già scritto.

**MISSIONE**:
1. Espandi le sezioni esistenti con dati aggiornati tramite Google Search.
2. Mantieni lo stile scorrevole.
3. Genera tag ancora più precisi se necessario.

**CONTENUTO ATTUALE**:
${currentResult.htmlContent}`;

        const response = await ai.models.generateContent({
            model: "gemini-3-flash-preview",
            contents: prompt,
            config: {
                responseMimeType: "application/json",
                responseSchema: responseSchema,
                tools: [{ googleSearch: {} }],
            },
        });

        const jsonText = response.text.trim();
        const result: SeoResult = JSON.parse(jsonText);

        const newSources = extractSources(response);
        const allSources = [...(currentResult.groundingSources || []), ...newSources];
        result.groundingSources = Array.from(new Map(allSources.map(s => [s.uri, s])).values());

        return result;
    } catch (error) {
        throw new Error("Errore durante l'espansione del contenuto.");
    }
};

const extractSources = (response: any): GroundingSource[] => {
    const sources: GroundingSource[] = [];
    const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;
    if (chunks) {
        chunks.forEach((chunk: any) => {
            if (chunk.web?.uri) {
                sources.push({
                    title: chunk.web.title || "Fonte Ufficiale",
                    uri: chunk.web.uri
                });
            }
        });
    }
    return Array.from(new Map(sources.map(s => [s.uri, s])).values());
};

export const generateImage = async (prompt: string): Promise<string> => {
    try {
        const response = await ai.models.generateImages({
            model: 'imagen-4.0-generate-001',
            prompt: `High-quality technical editorial illustration for blog: ${prompt}`,
            config: { numberOfImages: 1, outputMimeType: 'image/jpeg', aspectRatio: '16:9' },
        });
        return response.generatedImages?.[0]?.image.imageBytes || "";
    } catch (error) { return ""; }
};

