                <button onClick={handleCopy} className="text-slate-500 hover:text-indigo-400 p-1">
                    {copied ? <CheckIcon className="w-4 h-4 text-green-400" /> : <ClipboardIcon className="w-4 h-4" />}
                </button>
            </div>
        </div>
    );
};

