                            onChange={setArticleText}
                            onOptimize={addToQueue}
                            isLoading={isLoading}
                            onLoadClick={() => {}}
                            savedCount={savedArticles.length}
                            lastAutoSave={null}
                            onExportDB={() => {}}
                            onImportDB={() => {}}
                        />

                        <div className="bg-slate-800/50 p-6 rounded-2xl border border-slate-700 shadow-xl">
