export const optimizeArticleForSeo = async (articleText: string): Promise<SeoResult> => {
    try {
        const prompt = `Agisci come un esperto SEO Senior e AI Indexing Specialist. Trasforma il testo fornito seguendo rigorosamente i criteri SEO Yoast e i parametri di leggibilità per le AI.

**REQUISITI SEO (Yoast Style)**:
- Frase chiave nell'introduzione (primo paragrafo).
- Densità frase chiave ottimale.
- Frase chiave nel titolo SEO e nello slug.
- Suggerisci attributi ALT per immagini (anche se non presenti).
- Lunghezza testo minima 300 parole (mantieni la lunghezza originale).
- Titolo H1 unico.

**REQUISITI LEGGIBILITÀ**:
- Parole di transizione (quindi, inoltre, perciò) per legare il testo.
- Varietà nell'inizio delle frasi (evita frasi consecutive con la stessa parola).
- Lunghezza frasi contenuta (max 20 parole).
- Forma attiva prevalente.
- Paragrafi brevi e sottotitoli H2/H3 frequenti.

**STRUTTURA JSON DA GENERARE**:
{
  "html_content": {
    "title": "H1 titolo",
    "intro": "paragrafo hook (circa 50 parole)",
    "sections": [{"heading": "H2", "content": "testo", "type": "text|list|table"}],
    "faq": [{"question": "Domanda?", "answer": "Risposta."}],
    "conclusion": "Testo finale"
  },
  "schema_markup": {
    "article": { "@context": "https://schema.org", "@type": "BlogPosting", "headline": "...", "articleBody": "..." },
    "faq_schema": [{ "@type": "Question", "name": "...", "acceptedAnswer": { "@type": "Answer", "text": "..." } }]
  },
  "seo_metadata": { "yoast_focus_keyword": "...", "meta_description": "...", "slug": "...", "tags": ["tag1", "tag2"] }
}

Testo sorgente (NON TAGLIARE):
${articleText}`;

        const response = await ai.models.generateContent({
            model: "gemini-3-flash-preview",
            contents: prompt,
            config: {
                responseMimeType: "application/json",
                responseSchema: responseSchema,
                tools: [{ googleSearch: {} }],
            },
        });

        const result: SeoResult = JSON.parse(response.text.trim());

        // Costruisci htmlContent finale per la preview
        let fullHtml = `<p>${result.html_content.intro}</p>`;
        result.html_content.sections.forEach(s => {
            fullHtml += `<h2>${s.heading}</h2>`;
            if (s.type === 'list') {
                fullHtml += `<ul>${s.content.split('\n').map(li => `<li>${li.replace(/^[*-]\s*/, '')}</li>`).join('')}</ul>`;
            } else {
                fullHtml += `<p>${s.content}</p>`;
            }
        });
        if (result.html_content.faq.length > 0) {
            fullHtml += `<h2>Domande Frequenti (FAQ)</h2>`;
            result.html_content.faq.forEach(f => {
                fullHtml += `<h3>${f.question}</h3><p>${f.answer}</p>`;
            });
        }
        fullHtml += `<p><strong>Conclusione:</strong> ${result.html_content.conclusion}</p>`;

        result.htmlContent = fullHtml;
        result.groundingSources = extractSources(response);
        return result;
    } catch (error) {
        console.error(error);
        throw new Error("Errore durante l'ottimizzazione batch AI.");
    }
};

export const enrichArticleDepth = async (currentResult: SeoResult, originalText: string): Promise<SeoResult> => {
    try {
        const prompt = `Usa Google Search per trovare link ufficiali e fonti per questo articolo. Inseriscili come tag <a> nel testo HTML fornito senza cambiare la lunghezza o lo stile.
        Contenuto: ${currentResult.htmlContent}`;

        const response = await ai.models.generateContent({
            model: "gemini-3-flash-preview",
            contents: prompt,
            config: {
                tools: [{ googleSearch: {} }],
            },
        });

        const newHtml = response.text || currentResult.htmlContent;
        return { ...currentResult, htmlContent: newHtml };
    } catch (error) {
        return currentResult;
    }
};

const extractSources = (response: any): GroundingSource[] => {
    const sources: GroundingSource[] = [];
    const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;
    if (chunks) {
        chunks.forEach((chunk: any) => {
            if (chunk.web?.uri) {
                sources.push({
                    title: chunk.web.title || "Fonte Ufficiale",
                    uri: chunk.web.uri
                });
            }
        });
    }
    return Array.from(new Map(sources.map(s => [s.uri, s])).values());
};

