import React, { useState, useCallback, useMemo } from 'react';
import { SeoResult, GroundingSource } from '../types';
import { Loader } from './Loader';
import { ClipboardIcon, CheckIcon, EyeIcon, CodeBracketIcon, CheckCircleIcon, SparklesIcon, DocumentMagnifyingGlassIcon, PrinterIcon, BookmarkIcon } from './IconComponents';

interface SeoOutputProps {
    result: SeoResult | null;
    isLoading: boolean;
    isEnriching?: boolean;
    onIncreaseDepth?: () => void;
    error: string | null;
    onSave: (finalHtml?: string) => void;
}

const SeoDataItem: React.FC<{ label: string; value: string; mono?: boolean }> = ({ label, value, mono = false }) => {
    const [copied, setCopied] = useState(false);
    const handleCopy = () => {
        navigator.clipboard.writeText(value).then(() => {
            setCopied(true);
            setTimeout(() => setCopied(false), 2000);
        });
    };
    return (
        <div className="bg-slate-900/40 p-3 rounded-xl border border-slate-700/30 group">
            <label className="block text-[10px] uppercase font-bold text-slate-500 mb-1">{label}</label>
            <div className="flex justify-between items-center gap-2">
                <p className={`text-slate-200 text-sm truncate ${mono ? 'font-mono' : ''}`}>{value}</p>
                <button onClick={handleCopy} className="text-slate-500 hover:text-indigo-400 p-1">
                    {copied ? <CheckIcon className="w-4 h-4 text-green-400" /> : <ClipboardIcon className="w-4 h-4" />}
                </button>
            </div>
        </div>
    );
};

export const SeoOutput: React.FC<SeoOutputProps> = ({ result, isLoading, isEnriching, onIncreaseDepth, error, onSave }) => {
    const [activeTab, setActiveTab] = useState<'seo' | 'readability' | 'schema' | 'content'>('seo');
    const [viewMode, setViewMode] = useState<'preview' | 'code'>('preview');

    const wordCount = useMemo(() => {
        if (!result) return 0;
        // Rimuoviamo lo script per il conteggio parole reale
        const textOnly = result.htmlContent.replace(/<script\b[^>]*>([\s\S]*?)<\/script>/gim, "").replace(/<[^>]*>/g, ' ');
        return textOnly.trim().split(/\s+/).length;
    }, [result]);

    if (isLoading) return <div className="bg-slate-800/50 p-6 rounded-2xl border border-slate-700 h-full flex items-center justify-center"><Loader /></div>;
    if (error) return <div className="bg-slate-800/50 p-6 rounded-2xl border border-red-900/20 text-red-400 flex items-center justify-center text-center">{error}</div>;
    if (!result) return (
        <div className="bg-slate-800/50 p-12 rounded-2xl border border-slate-700 h-full flex flex-col items-center justify-center text-center text-slate-500">
            <SparklesIcon className="w-16 h-16 mb-4 opacity-20" />
            <p className="text-lg font-medium">Nessuna analisi attiva</p>
            <p className="text-sm">Seleziona un articolo dalla coda batch.</p>
        </div>
    );

    const fullSchemaJson = JSON.stringify({
        ...result.schema_markup.article,
        "mainEntity": {
            "@type": "FAQPage",
            "mainEntity": result.schema_markup.faq_schema
        }
    }, null, 2);

    return (
        <div className="bg-slate-800/50 rounded-2xl shadow-2xl border border-slate-700/50 flex flex-col h-full overflow-hidden">
            <div className="flex bg-slate-900/50 p-1 border-b border-slate-700/50 overflow-x-auto">
                {[
                    { id: 'seo', icon: DocumentMagnifyingGlassIcon, label: 'SEO Yoast' },
                    { id: 'readability', icon: SparklesIcon, label: 'Qualità' },
                    { id: 'schema', icon: CodeBracketIcon, label: 'Schema AI' },
                    { id: 'content', icon: EyeIcon, label: 'Articolo' }
                ].map(tab => (
                    <button
                        key={tab.id}
                        onClick={() => setActiveTab(tab.id as any)}
                        className={`flex-1 min-w-[100px] flex items-center justify-center gap-2 py-3 text-[10px] font-bold uppercase transition-all rounded-xl ${
                            activeTab === tab.id ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-500 hover:text-slate-300'
                        }`}
                    >
                        <tab.icon className="w-4 h-4" /> {tab.label}
                    </button>
                ))}
            </div>

            <div className="flex-1 overflow-y-auto p-6 space-y-6">
                {activeTab === 'seo' && (
                    <div className="space-y-6">
                        <div className="flex justify-between items-center bg-indigo-900/20 p-4 rounded-xl border border-indigo-500/20">
                            <div>
                                <h4 className="text-[10px] uppercase font-bold text-indigo-300">Word Count</h4>
                                <p className="text-2xl font-bold text-white">{wordCount}</p>
                            </div>
                            <button onClick={onIncreaseDepth} disabled={isEnriching} className="bg-indigo-600 text-white px-4 py-2 rounded-lg text-[10px] font-bold uppercase">
                                {isEnriching ? 'Cercando...' : 'Trova Link'}
                            </button>
                        </div>
                        <SeoDataItem label="Focus Keyword" value={result.seo_metadata.yoast_focus_keyword} mono />
                        <SeoDataItem label="Slug" value={result.seo_metadata.slug} mono />
                        <SeoDataItem label="Meta Description" value={result.seo_metadata.meta_description} />
                        <div className="bg-slate-900/40 p-3 rounded-xl border border-slate-700/30">
                            <label className="text-[10px] uppercase font-bold text-slate-500 block mb-2">Tag SEO</label>
                            <div className="flex flex-wrap gap-2">
                                {result.seo_metadata.tags.map((t, i) => (
                                    <span key={i} className="bg-slate-800 text-indigo-300 px-2 py-1 rounded text-[10px] border border-indigo-500/20">{t}</span>
                                ))}
                            </div>
                        </div>
                    </div>
                )}

                {activeTab === 'schema' && (
                    <div className="space-y-4">
                        <div className="flex justify-between items-center">
                            <h4 className="text-xs font-bold text-slate-400 uppercase">Schema.org JSON-LD</h4>
                            <button 
                                onClick={() => navigator.clipboard.writeText(fullSchemaJson)}
                                className="text-indigo-400 text-[10px] font-bold uppercase hover:underline"
                            >
                                Copia JSON-LD
                            </button>
                        </div>
                        <p className="text-[11px] text-slate-400 italic">Questo codice è già incluso automaticamente in fondo all'HTML dell'articolo.</p>
                        <pre className="bg-black/50 p-4 rounded-xl text-[10px] text-cyan-400 font-mono overflow-auto max-h-[500px] border border-slate-700">
                            {fullSchemaJson}
                        </pre>
                    </div>
                )}

                {activeTab === 'readability' && (
                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                        {result.readability.map((r, i) => (
                            <div key={i} className="bg-slate-900/30 p-4 rounded-xl border border-slate-700/30">
                                <div className="flex justify-between items-center mb-1">
                                    <span className="text-xs font-bold text-slate-200">{r.criteria}</span>
                                    <span className={`text-[10px] font-bold ${r.status === 'good' ? 'text-green-400' : 'text-yellow-400'}`}>{r.score}</span>
                                </div>
                                <p className="text-[11px] text-slate-400 leading-snug">{r.message}</p>
                            </div>
                        ))}
                    </div>
                )}

                {activeTab === 'content' && (
                    <div className="space-y-4">
                        <div className="flex items-center justify-between mb-4">
                            <div className="flex bg-slate-900 p-1 rounded-lg border border-slate-700">
                                <button onClick={() => setViewMode('preview')} className={`px-4 py-1.5 text-[10px] font-bold rounded-md ${viewMode === 'preview' ? 'bg-indigo-600 text-white' : 'text-slate-500'}`}>ANTEPRIMA</button>
                                <button onClick={() => setViewMode('code')} className={`px-4 py-1.5 text-[10px] font-bold rounded-md ${viewMode === 'code' ? 'bg-indigo-600 text-white' : 'text-slate-500'}`}>HTML + SCHEMA AI</button>
                            </div>
                            <button onClick={() => onSave()} className="bg-emerald-600 p-2 rounded-xl text-white hover:bg-emerald-500 transition-colors"><BookmarkIcon className="w-5 h-5" /></button>
                        </div>

                        <div className="bg-white rounded-2xl overflow-hidden min-h-[600px] border border-slate-700 relative">
                            {viewMode === 'preview' ? (
                                <iframe 
                                    srcDoc={`<html><head><style>
                                        body{font-family:sans-serif; line-height:1.6; color:#334; padding:30px; max-width:700px; margin:0 auto;} 
                                        h1{color:#112; border-bottom:2px solid #6366f1; padding-bottom:10px;}
                                        h2{color:#4338ca; margin-top:30px;}
                                        h3{color:#1e293b;}
                                        p{margin-bottom:1em;}
                                        a{color:#4f46e5; text-decoration:underline;}
                                        ul{padding-left:20px;}
                                        script{display:none;}
                                    </style></head><body>
                                        ${result.htmlContent}
                                    </body></html>`}
                                    className="w-full h-[600px]"
                                />
                            ) : (
                                <div className="p-6 bg-slate-950 h-[600px] overflow-auto font-mono text-[11px] text-cyan-400/90 whitespace-pre-wrap">
                                    {result.htmlContent}
                                </div>
                            )}
                        </div>
                    </div>
                )}
            </div>
        </div>
    );
};

