  uri: string;
}

export interface SeoResult {
  html_content: {
    title: string;
    intro: string;
    sections: { heading: string; content: string; type: 'text' | 'list' | 'table' }[];
    faq: { question: string; answer: string }[];
    conclusion: string;
  };
  schema_markup: {
    article: any;
    faq_schema: any[];
  };
  seo_metadata: {
    yoast_focus_keyword: string;
    meta_description: string;
    slug: string;
    tags: string[];
    category: string;
  };
  social_post: {
    platform: string;
    content: string;
    hashtags: string[];
  };
  // Per compatibilità con UI esistente
