export const optimizeArticleForSeo = async (articleText: string): Promise<SeoResult> => {
    try {
        const prompt = `Agisci come un esperto SEO Senior e AI Indexing Specialist. Trasforma il testo fornito seguendo i criteri SEO Yoast e prepara i materiali per la distribuzione.

**REQUISITI SEO**:
- Frase chiave in H1, Slug e primo paragrafo.
- Meta Description magnetica.
- Scegli una Categoria SEO pertinente e 5 Tag.

**REQUISITI SOCIAL**:
- Scrivi un post promozionale per LinkedIn/Facebook (tono professionale ma coinvolgente).
- Includi una call to action e gli hashtag più performanti.

**STRUTTURA JSON**:
{
  "html_content": { ... },
  "schema_markup": { ... },
  "seo_metadata": { ..., "category": "Categoria scelta", "tags": ["tag1", ...] },
  "social_post": { "platform": "LinkedIn", "content": "Il copy del post", "hashtags": ["#seo", ...] }
}

Testo sorgente:
${articleText}`;

        const response = await ai.models.generateContent({
            model: "gemini-3-flash-preview",
            contents: prompt,
            config: {
                responseMimeType: "application/json",
                responseSchema: responseSchema,
                tools: [{ googleSearch: {} }],
            },
        });

        const result: SeoResult = JSON.parse(response.text.trim());

        let fullHtml = `<h1>${result.html_content.title}</h1>`;
        fullHtml += `<p>${result.html_content.intro}</p>`;
        result.html_content.sections.forEach(s => {
            fullHtml += `<h2>${s.heading}</h2>`;
            if (s.type === 'list') {
                fullHtml += `<ul>${s.content.split('\n').map(li => {
                    const cleanLi = li.replace(/^[*-]\s*/, '').trim();
                    return cleanLi ? `<li>${cleanLi}</li>` : '';
                }).join('')}</ul>`;
            } else {
                fullHtml += `<p>${s.content}</p>`;
            }
        });

        if (result.html_content.faq.length > 0) {
            fullHtml += `<h2>Domande Frequenti (FAQ)</h2>`;
            result.html_content.faq.forEach(f => {
                fullHtml += `<h3>${f.question}</h3><p>${f.answer}</p>`;
            });
        }
        fullHtml += `<p><strong>Conclusione:</strong> ${result.html_content.conclusion}</p>`;

        const fullSchema = {
            ...result.schema_markup.article,
            "mainEntity": {
                "@type": "FAQPage",
                "mainEntity": result.schema_markup.faq_schema
            }
        };
        const schemaScript = `\n\n<!-- Schema.org JSON-LD per indicizzazione AI -->\n<script type="application/ld+json">\n${JSON.stringify(fullSchema, null, 2)}\n</script>`;

        result.htmlContent = fullHtml + schemaScript;
        result.groundingSources = extractSources(response);
        return result;
    } catch (error) {
        console.error(error);
        throw new Error("Errore durante l'ottimizzazione batch AI.");
    }
};

export const enrichArticleDepth = async (currentResult: SeoResult, originalText: string): Promise<SeoResult> => {
    try {
        const prompt = `Usa Google Search per trovare link ufficiali e fonti per questo articolo. Inseriscili come tag <a> nel testo HTML fornito. Mantieni intatto lo script JSON-LD alla fine.
        Contenuto: ${currentResult.htmlContent}`;

        const response = await ai.models.generateContent({
            model: "gemini-3-flash-preview",
            contents: prompt,
            config: { tools: [{ googleSearch: {} }] },
        });

        const newHtml = response.text || currentResult.htmlContent;
        return { ...currentResult, htmlContent: newHtml };
    } catch (error) {
        return currentResult;
    }
};

const extractSources = (response: any): GroundingSource[] => {
    const sources: GroundingSource[] = [];
    const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;
    if (chunks) {
        chunks.forEach((chunk: any) => {
            if (chunk.web?.uri) {
                sources.push({
                    title: chunk.web.title || "Fonte Ufficiale",
                    uri: chunk.web.uri
                });
            }
        });
    }
    return Array.from(new Map(sources.map(s => [s.uri, s])).values());
};

