const slugify = (text: string) => text.toLowerCase().replace(/[^\w ]+/g, '').replace(/ +/g, '-');

export const optimizeArticleForSeo = async (articleText: string): Promise<SeoResult> => {
    try {
        const prompt = `Agisci come un esperto SEO Senior e AI Indexing Specialist. Trasforma il testo fornito seguendo rigorosamente i criteri SEO Yoast e riorganizzalo per massimizzare la leggibilità da parte dei crawler AI (Google Gemini, ChatGPT, Perplexity).

**REQUISITI STRUTTURALI PER AI CRAWLER**:
- Genera un'introduzione magnetica (40-80 parole).
- Prepara i titoli H2 e H3 in modo che siano descrittivi.
- Inserisci FAQ basate sulle ricerche correlate.

**REQUISITI SEO**:
- Titolo SEO (seo_title): Ottimizzato per la CTR, max 60 caratteri.
- Frase chiave in H1, Slug e primo paragrafo.
- Meta Description magnetica (max 155 caratteri).
- Scegli una Categoria SEO pertinente e almeno 5 Tag rilevanti.

**REQUISITI SOCIAL**:
- Genera un post per LinkedIn/Facebook coinvolgente.

Testo sorgente:
${articleText}`;

        const response = await ai.models.generateContent({
            model: "gemini-3-flash-preview",
            contents: prompt,
            config: {
                responseMimeType: "application/json",
                responseSchema: responseSchema,
                tools: [{ googleSearch: {} }],
            },
        });

        const result: SeoResult = JSON.parse(response.text.trim());

        // Costruzione HTML con Indice e Ancore
        let fullHtml = `<h1>${result.html_content.title}</h1>`;
        fullHtml += `<p>${result.html_content.intro}</p>`;

        // 1. Generazione Indice (ToC)
        let toc = `<div class="table-of-contents" style="background:#f8fafc; border:1px solid #e2e8f0; padding:20px; border-radius:12px; margin:20px 0;">`;
        toc += `<p style="margin-top:0; font-weight:bold; color:#1e293b;">Indice dell'articolo</p><ul style="margin-bottom:0; padding-left:20px;">`;

        result.html_content.sections.forEach(s => {
            const sId = slugify(s.heading);
            toc += `<li><a href="#${sId}">${s.heading}</a>`;
            if (s.subsections && s.subsections.length > 0) {
                toc += `<ul style="font-size:0.9em;">`;
                s.subsections.forEach(sub => {
                    toc += `<li><a href="#${slugify(sub.heading)}">${sub.heading}</a></li>`;
                });
                toc += `</ul>`;
            }
            toc += `</li>`;
        });

        if (result.html_content.faq.length > 0) {
            toc += `<li><a href="#faq-sezione">Domande Frequenti (FAQ)</a></li>`;
        }
        toc += `</ul></div>`;

        fullHtml += toc;

        // 2. Generazione Sezioni con ID
        result.html_content.sections.forEach(s => {
            const sId = slugify(s.heading);
            fullHtml += `<h2 id="${sId}">${s.heading}</h2>`;
            if (s.type === 'list') {
                fullHtml += `<ul>${s.content.split('\n').map(li => {
                    const cleanLi = li.replace(/^[*-]\s*/, '').trim();
                    return cleanLi ? `<li>${cleanLi}</li>` : '';
                }).join('')}</ul>`;
            } else {
                fullHtml += `<p>${s.content}</p>`;
            }

            if (s.subsections) {
                s.subsections.forEach(sub => {
                    fullHtml += `<h3 id="${slugify(sub.heading)}">${sub.heading}</h3>`;
                    fullHtml += `<p>${sub.content}</p>`;
                });
            }
        });

        if (result.html_content.faq.length > 0) {
            fullHtml += `<h2 id="faq-sezione">Domande Frequenti (FAQ)</h2>`;
            result.html_content.faq.forEach(f => {
                fullHtml += `<h3>${f.question}</h3><p>${f.answer}</p>`;
            });
        }
        fullHtml += `<p><strong>Conclusione:</strong> ${result.html_content.conclusion}</p>`;

        const fullSchema = {
            ...result.schema_markup.article,
            "mainEntity": {
                "@type": "FAQPage",
                "mainEntity": result.schema_markup.faq_schema
            }
        };
        const schemaScript = `\n\n<!-- Schema.org JSON-LD per indicizzazione AI -->\n<script type="application/ld+json">\n${JSON.stringify(fullSchema, null, 2)}\n</script>`;

        result.htmlContent = fullHtml + schemaScript;
        result.groundingSources = extractSources(response);
        return result;
    } catch (error) {
        console.error(error);
        throw new Error("Errore durante l'ottimizzazione batch AI.");
    }
};

export const enrichArticleDepth = async (currentResult: SeoResult, originalText: string): Promise<SeoResult> => {
    try {
        const prompt = `Usa Google Search per trovare link ufficiali e fonti per questo articolo. Inseriscili come tag <a> nel testo HTML fornito. Mantieni intatto l'indice e lo script JSON-LD.
        Contenuto: ${currentResult.htmlContent}`;

        const response = await ai.models.generateContent({
            model: "gemini-3-flash-preview",
            contents: prompt,
            config: { tools: [{ googleSearch: {} }] },
        });

        const newHtml = response.text || currentResult.htmlContent;
        return { ...currentResult, htmlContent: newHtml };
    } catch (error) {
        return currentResult;
    }
};

const extractSources = (response: any): GroundingSource[] => {
    const sources: GroundingSource[] = [];
    const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;
    if (chunks) {
        chunks.forEach((chunk: any) => {
            if (chunk.web?.uri) {
                sources.push({
                    title: chunk.web.title || "Fonte Ufficiale",
                    uri: chunk.web.uri
                });
            }
        });
    }
    return Array.from(new Map(sources.map(s => [s.uri, s])).values());
};

