const slugify = (text: string) => text.toLowerCase().replace(/[^\w ]+/g, '').replace(/ +/g, '-');

export const optimizeArticleForSeo = async (articleText: string): Promise<SeoResult> => {
    try {
        const prompt = `Agisci come un Senior SEO & AI Crawler Specialist. Analizza e riorganizza il testo fornito per massimizzare l'indicizzazione da parte di bot come Google Gemini, ChatGPT e Perplexity.

**REGOLE STRUTTURALI MANDATORIE**:
1. **Unico H1**: Assicurati che esista un solo <h1>. Trasforma ogni altro titolo principale in <h2>.
2. **Snippet Introduttivo**: Il primo paragrafo DEVE essere una sintesi tra 40 e 80 parole, ottimizzata come "featured snippet".
3. **Alt-Text Immagini**: Se nel testo originale sono presenti tag <img> (o riferimenti a immagini), genera attributi alt="descrizione descrittiva" basati sul contesto circostante.
4. **Meta Description**: Genera una descrizione SEO pulita tra 140-160 caratteri.
5. **Indice Automatico**: Prepara la lista di titoli per un indice con ancore.

Testo Sorgente:
${articleText}`;

        const response = await ai.models.generateContent({
            model: "gemini-3-flash-preview",
            contents: prompt,
            config: {
                responseMimeType: "application/json",
                responseSchema: responseSchema,
                tools: [{ googleSearch: {} }],
            },
        });

        const result: SeoResult = JSON.parse(response.text.trim());

        // Costruzione HTML Avanzata
        let fullHtml = `<!-- Meta SEO -->\n<meta name="description" content="${result.seo_metadata.meta_description}">\n\n`;
        fullHtml += `<h1>${result.html_content.title}</h1>\n`;
        fullHtml += `<p>${result.html_content.intro}</p>\n\n`;

        // 1. Box Indice (ToC) stilizzato
        let toc = `<div class="table-of-contents" style="background:#f1f5f9; border:1px solid #cbd5e1; padding:25px; border-radius:12px; margin:30px 0;">\n`;
        toc += `<p style="margin-top:0; font-weight:bold; color:#0f172a; border-bottom:1px solid #cbd5e1; padding-bottom:10px;">Indice dei contenuti</p>\n`;
        toc += `<ul style="margin-bottom:0; padding-left:20px; list-style-type:square; color:#475569;">\n`;

        result.html_content.sections.forEach(s => {
            const sId = slugify(s.heading);
            toc += `  <li><a href="#${sId}" style="color:#2563eb; text-decoration:none;">${s.heading}</a>`;
            if (s.subsections && s.subsections.length > 0) {
                toc += `\n    <ul style="font-size:0.9em; padding-left:15px; margin-top:5px;">\n`;
                s.subsections.forEach(sub => {
                    toc += `      <li><a href="#${slugify(sub.heading)}" style="color:#64748b; text-decoration:none;">${sub.heading}</a></li>\n`;
                });
                toc += `    </ul>\n`;
            }
            toc += `</li>\n`;
        });

        if (result.html_content.faq.length > 0) {
            toc += `  <li><a href="#faq-sezione" style="color:#2563eb; text-decoration:none;">Domande Frequenti (FAQ)</a></li>\n`;
        }
        toc += `</ul>\n</div>\n\n`;

        fullHtml += toc;

        // 2. Rendering Sezioni con ID e tag semantici
        result.html_content.sections.forEach(s => {
            const sId = slugify(s.heading);
            fullHtml += `<h2 id="${sId}">${s.heading}</h2>\n`;

            if (s.type === 'list') {
                fullHtml += `<ul>\n${s.content.split('\n').filter(l => l.trim()).map(li => `  <li>${li.replace(/^[*-]\s*/, '').trim()}</li>`).join('\n')}\n</ul>\n`;
            } else if (s.type === 'table') {
                fullHtml += `<div style="overflow-x:auto;"><table border="1" style="width:100%; border-collapse:collapse; margin-bottom:20px;">\n${s.content}</table></div>\n`;
            } else {
                fullHtml += `<p>${s.content}</p>\n`;
            }

            if (s.subsections) {
                s.subsections.forEach(sub => {
                    fullHtml += `<h3 id="${slugify(sub.heading)}">${sub.heading}</h3>\n`;
                    fullHtml += `<p>${sub.content}</p>\n`;
                });
            }
        });

        // 3. FAQ Section
        if (result.html_content.faq.length > 0) {
            fullHtml += `<h2 id="faq-sezione">Domande Frequenti (FAQ)</h2>\n`;
            result.html_content.faq.forEach(f => {
                fullHtml += `<div class="faq-item" style="margin-bottom:20px;">\n  <h3 style="margin-bottom:5px;">${f.question}</h3>\n  <p>${f.answer}</p>\n</div>\n`;
            });
        }

        fullHtml += `<p><strong>Conclusione:</strong> ${result.html_content.conclusion}</p>\n`;

        // 4. Schema.org Iniezione
        const fullSchema = {
            ...result.schema_markup.article,
            "description": result.seo_metadata.meta_description,
            "mainEntity": {
                "@type": "FAQPage",
                "mainEntity": result.schema_markup.faq_schema
            }
        };
        const schemaScript = `\n\n<!-- Schema.org JSON-LD - AI Optimization -->\n<script type="application/ld+json">\n${JSON.stringify(fullSchema, null, 2)}\n</script>`;

        result.htmlContent = fullHtml + schemaScript;
        result.groundingSources = extractSources(response);
        return result;
    } catch (error) {
        console.error(error);
        throw new Error("Errore durante l'ottimizzazione SEO AI.");
    }
};

export const enrichArticleDepth = async (currentResult: SeoResult, originalText: string): Promise<SeoResult> => {
    try {
        const prompt = `Cerca fonti autorevoli e link ufficiali per approfondire questo articolo. Inseriscili come link <a> naturali nel testo. Mantieni gli ID delle ancore e l'unico H1.
        Contenuto: ${currentResult.htmlContent}`;

        const response = await ai.models.generateContent({
            model: "gemini-3-flash-preview",
            contents: prompt,
            config: { tools: [{ googleSearch: {} }] },
        });

        const newHtml = response.text || currentResult.htmlContent;
        return { ...currentResult, htmlContent: newHtml };
    } catch (error) {
        return currentResult;
    }
};

const extractSources = (response: any): GroundingSource[] => {
    const sources: GroundingSource[] = [];
    const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;
    if (chunks) {
        chunks.forEach((chunk: any) => {
            if (chunk.web?.uri) {
                sources.push({
                    title: chunk.web.title || "Fonte",
                    uri: chunk.web.uri
                });
            }
        });
    }
    return Array.from(new Map(sources.map(s => [s.uri, s])).values());
};

import React, { useState, useCallback, useMemo } from 'react';
import { SeoResult, GroundingSource } from '../types';
import { Loader } from './Loader';
import { ClipboardIcon, CheckIcon, EyeIcon, CodeBracketIcon, CheckCircleIcon, SparklesIcon, DocumentMagnifyingGlassIcon, PrinterIcon, BookmarkIcon } from './IconComponents';

interface SeoOutputProps {
    result: SeoResult | null;
    isLoading: boolean;
    isEnriching?: boolean;
    onIncreaseDepth?: () => void;
    error: string | null;
    onSave: (finalHtml?: string) => void;
}

const SeoDataItem: React.FC<{ label: string; value: string; mono?: boolean }> = ({ label, value, mono = false }) => {
    const [copied, setCopied] = useState(false);
    const handleCopy = () => {
        navigator.clipboard.writeText(value).then(() => {
            setCopied(true);
            setTimeout(() => setCopied(false), 2000);
        });
    };
    return (
        <div className="bg-slate-900/40 p-3 rounded-xl border border-slate-700/30 group">
            <label className="block text-[10px] uppercase font-bold text-slate-500 mb-1">{label}</label>
            <div className="flex justify-between items-center gap-2">
                <p className={`text-slate-200 text-sm truncate ${mono ? 'font-mono' : ''}`} title={value}>{value}</p>
                <button onClick={handleCopy} className="text-slate-500 hover:text-indigo-400 p-1 flex-shrink-0">
                    {copied ? <CheckIcon className="w-4 h-4 text-green-400" /> : <ClipboardIcon className="w-4 h-4" />}
                </button>
            </div>
        </div>
    );
};

