const slugify = (text: string) => text.toLowerCase().replace(/[^\w ]+/g, '').replace(/ +/g, '-');

export const optimizeArticleForSeo = async (articleText: string): Promise<SeoResult> => {
    try {
        const prompt = `Agisci come un Esperto di Architettura HTML per AI e SEO. Trasforma il testo fornito seguendo rigorosamente queste regole strutturali:

1. **GERARCHIA TITOLI**: Un solo <h1> per il titolo. Titoli di sezione <h2>. Titoli FAQ e sottosezioni <h3>.
2. **INDICE UNICO (ToC)**: Crea un indice ipertestuale all'inizio, dopo l'intro, in un box stilizzato. NON ripetere mai l'indice altrove.
3. **REGOLE TABELLE**: Usa <table> solo per dati (prezzi, confronti). DIVIETO ASSOLUTO di inserire paragrafi descrittivi dentro le celle. Usa <thead> e <tbody>.
4. **ACCESSIBILITÀ IMMAGINI**: Genera tag <img src="placeholder.jpg" alt="..."> con alt-text descrittivi basati sul contesto se appropriato.
5. **SNIPPET AI**: Primo paragrafo tra 40-80 parole, diretto e informativo.
6. **ID UNIVOCI**: Ogni <h2> e <h3> DEVE avere un id slug-friendly (es: id="titolo-sezione") corrispondente ai link nel ToC.

Testo Sorgente:
${articleText}`;

        const response = await ai.models.generateContent({
            model: "gemini-3-flash-preview",
            contents: prompt,
            config: {
                responseMimeType: "application/json",
                responseSchema: responseSchema,
                tools: [{ googleSearch: {} }],
            },
        });

        const result: SeoResult = JSON.parse(response.text.trim());

        // Costruzione HTML Rigorosa
        let fullHtml = `<!-- Meta SEO -->\n<meta name="description" content="${result.seo_metadata.meta_description}">\n\n`;
        fullHtml += `<h1>${result.html_content.title}</h1>\n`;
        fullHtml += `<p>${result.html_content.intro}</p>\n\n`;

        // 1. Box Indice Unico
        let toc = `<div class="table-of-contents" style="background:#f8fafc; border:1px solid #e2e8f0; padding:25px; border-radius:12px; margin:30px 0;">\n`;
        toc += `<p style="margin-top:0; font-weight:bold; color:#1e293b;">Indice dei contenuti</p>\n`;
        toc += `<ul style="margin-bottom:0; padding-left:20px; color:#475569;">\n`;

        result.html_content.sections.forEach(s => {
            const sId = slugify(s.heading);
            toc += `  <li><a href="#${sId}">${s.heading}</a>`;
            if (s.subsections && s.subsections.length > 0) {
                toc += `\n    <ul style="font-size:0.9em; padding-left:15px; margin-top:5px;">\n`;
                s.subsections.forEach(sub => {
                    toc += `      <li><a href="#${slugify(sub.heading)}">${sub.heading}</a></li>\n`;
                });
                toc += `    </ul>\n`;
            }
            toc += `</li>\n`;
        });

        if (result.html_content.faq.length > 0) {
            toc += `  <li><a href="#faq-sezione">Domande Frequenti (FAQ)</a></li>\n`;
        }
        toc += `</ul>\n</div>\n\n`;
        fullHtml += toc;

        // 2. Rendering Sezioni con Validazione Tabelle
        result.html_content.sections.forEach(s => {
            const sId = slugify(s.heading);
            fullHtml += `<h2 id="${sId}">${s.heading}</h2>\n`;

            if (s.type === 'list') {
                fullHtml += `<ul>\n${s.content.split('\n').filter(l => l.trim()).map(li => `  <li>${li.replace(/^[*-]\s*/, '').trim()}</li>`).join('\n')}\n</ul>\n`;
            } else if (s.type === 'table') {
                // Avvolge la tabella in un div scrollabile e assicura thead/tbody
                fullHtml += `<div style="overflow-x:auto; margin-bottom:25px;">\n<table style="width:100%; border-collapse:collapse; border:1px solid #e2e8f0;">\n`;
                // Se il contenuto non ha già thead, lo generiamo noi o assumiamo che l'IA lo faccia correttamente
                fullHtml += `${s.content}\n</table>\n</div>\n`;
            } else {
                fullHtml += `<p>${s.content}</p>\n`;
            }

            if (s.subsections) {
                s.subsections.forEach(sub => {
                    fullHtml += `<h3 id="${slugify(sub.heading)}">${sub.heading}</h3>\n`;
                    fullHtml += `<p>${sub.content}</p>\n`;
                });
            }
        });

        // 3. Sezione FAQ Rigorosa
        if (result.html_content.faq.length > 0) {
            fullHtml += `<h2 id="faq-sezione">Domande Frequenti (FAQ)</h2>\n`;
            result.html_content.faq.forEach(f => {
                const fId = slugify(f.question);
                fullHtml += `<div class="faq-item" style="margin-bottom:20px;">\n  <h3 id="${fId}">${f.question}</h3>\n  <p>${f.answer}</p>\n</div>\n`;
            });
        }

        fullHtml += `<p><strong>Conclusione:</strong> ${result.html_content.conclusion}</p>\n`;

        // 4. Iniezione JSON-LD come ultima parte
        const fullSchema = {
            ...result.schema_markup.article,
            "description": result.seo_metadata.meta_description,
            "mainEntity": {
                "@type": "FAQPage",
                "mainEntity": result.schema_markup.faq_schema
            }
        };
        const schemaScript = `\n\n<!-- Schema.org JSON-LD -->\n<script type="application/ld+json">\n${JSON.stringify(fullSchema, null, 2)}\n</script>`;

        result.htmlContent = fullHtml + schemaScript;
        result.groundingSources = extractSources(response);
        return result;
    } catch (error) {
        console.error(error);
        throw new Error("Errore durante l'ottimizzazione SEO AI.");
    }
};

export const enrichArticleDepth = async (currentResult: SeoResult, originalText: string): Promise<SeoResult> => {
    try {
        const prompt = `Arricchisci questo HTML con link autorevoli senza rompere la struttura degli ID, delle tabelle o della gerarchia H1-H2-H3.
        Contenuto: ${currentResult.htmlContent}`;

        const response = await ai.models.generateContent({
            model: "gemini-3-flash-preview",
            contents: prompt,
            config: { tools: [{ googleSearch: {} }] },
        });

        return { ...currentResult, htmlContent: response.text || currentResult.htmlContent };
    } catch (error) {
        return currentResult;
    }
};

const extractSources = (response: any): GroundingSource[] => {
    const sources: GroundingSource[] = [];
    const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;
    if (chunks) {
        chunks.forEach((chunk: any) => {
            if (chunk.web?.uri) {
                sources.push({
                    title: chunk.web.title || "Fonte",
                    uri: chunk.web.uri
                });
            }
        });
    }
    return Array.from(new Map(sources.map(s => [s.uri, s])).values());
};

