const slugify = (text: string) => text.toLowerCase().replace(/[^\w ]+/g, '').replace(/ +/g, '-');

export const optimizeArticleForSeo = async (articleText: string): Promise<SeoResult> => {
    try {
        const prompt = `Agisci come Ottimizzatore SEO Senior per WordPress. Segui queste regole "ZERO TOLERANCE":

1. **INDICE (ToC)**: NON GENERARE MAI l'indice dei contenuti. Sarà gestito da un plugin esterno.
2. **TITOLI E ANCORE**: Un solo <h1>. Ogni <h2> e <h3> DEVE avere un attributo id univoco e descrittivo (es: <h2 id="slug-titolo">).
3. **SNIPPET INTRO**: Il primo paragrafo (Intro) deve essere tra 40 e 80 parole, informativo e senza tag annidati.
4. **PULIZIA TABELLE**: Solo dati puri. È VIETATO inserire paragrafi <p> o testo libero dentro <table>. Solo <thead>, <tbody>, <tr>, <th>, <td>.
5. **DIVIETO ANNIDAMENTO**: Mai tabelle dentro tabelle. Mai tag <p> vuoti attorno a immagini o tabelle.

Testo Sorgente:
${articleText}`;

        const response = await ai.models.generateContent({
            model: "gemini-3-flash-preview",
            contents: prompt,
            config: {
                responseMimeType: "application/json",
                responseSchema: responseSchema,
                tools: [{ googleSearch: {} }],
            },
        });

        const result: SeoResult = JSON.parse(response.text.trim());

        // Costruzione HTML Rigorosa per WordPress
        let fullHtml = `<meta name="description" content="${result.seo_metadata.meta_description}">\n\n`;
        fullHtml += `<h1>${result.html_content.title}</h1>\n`;
        fullHtml += `<p>${result.html_content.intro}</p>\n\n`;

        // Rendering Sezioni
        result.html_content.sections.forEach(s => {
            const sId = slugify(s.heading);
            fullHtml += `<h2 id="${sId}">${s.heading}</h2>\n`;

            if (s.type === 'list') {
                fullHtml += `<ul>\n${s.content.split('\n').filter(l => l.trim()).map(li => `  <li>${li.replace(/^[*-]\s*/, '').trim()}</li>`).join('\n')}\n</ul>\n`;
            } else if (s.type === 'table') {
                fullHtml += `<div style="overflow-x:auto;">\n<table border="1" style="width:100%; border-collapse:collapse;">\n${s.content}\n</table>\n</div>\n`;
            } else {
                fullHtml += `<p>${s.content}</p>\n`;
            }

            if (s.subsections) {
                s.subsections.forEach(sub => {
                    fullHtml += `<h3 id="${slugify(sub.heading)}">${sub.heading}</h3>\n`;
                    fullHtml += `<p>${sub.content}</p>\n`;
                });
            }
        });

        // Sezione FAQ
        if (result.html_content.faq.length > 0) {
            fullHtml += `<h2 id="faq-sezione-domande">Domande Frequenti (FAQ)</h2>\n`;
            result.html_content.faq.forEach(f => {
                const fId = slugify(f.question);
                fullHtml += `<div class="faq-item">\n  <h3 id="${fId}">${f.question}</h3>\n  <p>${f.answer}</p>\n</div>\n`;
            });
        }

        fullHtml += `<p><strong>Conclusione:</strong> ${result.html_content.conclusion}</p>\n`;

        // Schema.org - Blocco unico senza commenti interni
        const fullSchema = {
            ...result.schema_markup.article,
            "description": result.seo_metadata.meta_description,
            "mainEntity": {
                "@type": "FAQPage",
                "mainEntity": result.schema_markup.faq_schema
            }
        };
        const schemaScript = `\n\n<script type="application/ld+json">\n${JSON.stringify(fullSchema)}\n</script>`;

        result.htmlContent = fullHtml + schemaScript;
        result.groundingSources = extractSources(response);
        return result;
    } catch (error) {
        console.error(error);
        throw new Error("Errore durante l'ottimizzazione SEO AI.");
    }
};

export const enrichArticleDepth = async (currentResult: SeoResult, originalText: string): Promise<SeoResult> => {
    try {
        const prompt = `Arricchisci l'HTML fornito con link autorevoli ufficiali. RISPETTA gli ID esistenti. NON aggiungere indici o box TOC.
        Contenuto: ${currentResult.htmlContent}`;

        const response = await ai.models.generateContent({
            model: "gemini-3-flash-preview",
            contents: prompt,
            config: { tools: [{ googleSearch: {} }] },
        });

        return { ...currentResult, htmlContent: response.text || currentResult.htmlContent };
    } catch (error) {
        return currentResult;
    }
};

const extractSources = (response: any): GroundingSource[] => {
    const sources: GroundingSource[] = [];
    const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;
    if (chunks) {
        chunks.forEach((chunk: any) => {
            if (chunk.web?.uri) {
                sources.push({
                    title: chunk.web.title || "Fonte",
                    uri: chunk.web.uri
                });
            }
        });
    }
    return Array.from(new Map(sources.map(s => [s.uri, s])).values());
};

