const slugify = (text: string) => text.toLowerCase().replace(/[^\w ]+/g, '').replace(/ +/g, '-');

export const optimizeArticleForSeo = async (articleText: string): Promise<SeoResult> => {
    try {
        const prompt = `Agisci come Editor Tecnico Esperto SEO per WordPress. Trasforma il testo fornito in un codice HTML perfetto per l'AI Indexing.

REGOLE MANDATORIE:
1. **INTEGRITÀ TOTALE**: NON accorciare il testo originale. Mantieni tutti i paragrafi e le spiegazioni. NON fare riassunti.
2. **NO INDICE (ToC)**: È VIETATO generare l'indice dei contenuti o box ToC.
3. **TITOLI E ANCORAGGI**: Un solo <h1>. Ogni <h2> e <h3> DEVE avere un attributo id unico e descrittivo (es: <h2 id="titolo-sezione">).
4. **PULIZIA TABELLE**: È ASSOLUTAMENTE VIETATO inserire paragrafi <p> o testo libero dentro <table>. La tabella deve contenere solo dati puri in <thead> e <tbody>.
5. **SNIPPET INIZIALE**: Primo paragrafo tra 40-80 parole, informativo e diretto.
6. **METADATI**: Genera una Meta Description efficace.
7. **JSON-LD**: Crea uno script JSON-LD completo (TechArticle + FAQPage).

Testo Sorgente:
${articleText}`;

        const response = await ai.models.generateContent({
            model: "gemini-3-flash-preview",
            contents: prompt,
            config: {
                responseMimeType: "application/json",
                responseSchema: responseSchema,
                tools: [{ googleSearch: {} }],
            },
        });

        const result: SeoResult = JSON.parse(response.text.trim());

        // Costruzione HTML Rigorosa per WordPress (senza ToC)
        let fullHtml = `<meta name="description" content="${result.seo_metadata.meta_description}">\n\n`;
        fullHtml += `<h1>${result.html_content.title}</h1>\n`;
        fullHtml += `<p>${result.html_content.intro}</p>\n\n`;

        result.html_content.sections.forEach(s => {
            const sId = slugify(s.heading);
            fullHtml += `<h2 id="${sId}">${s.heading}</h2>\n`;

            if (s.type === 'list') {
                fullHtml += `<ul>\n${s.content.split('\n').filter(l => l.trim()).map(li => `  <li>${li.replace(/^[*-]\s*/, '').trim()}</li>`).join('\n')}\n</ul>\n`;
            } else if (s.type === 'table') {
                fullHtml += `<div style="overflow-x:auto; margin-bottom:20px;">\n<table border="1" style="width:100%; border-collapse:collapse;">\n${s.content}\n</table>\n</div>\n`;
            } else {
                fullHtml += `<p>${s.content}</p>\n`;
            }

            if (s.subsections) {
                s.subsections.forEach(sub => {
                    fullHtml += `<h3 id="${slugify(sub.heading)}">${sub.heading}</h3>\n`;
                    fullHtml += `<p>${sub.content}</p>\n`;
                });
            }
        });

        if (result.html_content.faq.length > 0) {
            fullHtml += `<h2 id="faq-sezione-domande">Domande Frequenti (FAQ)</h2>\n`;
            result.html_content.faq.forEach(f => {
                const fId = slugify(f.question);
                fullHtml += `<div class="faq-item">\n  <h3 id="${fId}">${f.question}</h3>\n  <p>${f.answer}</p>\n</div>\n`;
            });
        }

        fullHtml += `<p><strong>Conclusione:</strong> ${result.html_content.conclusion}</p>\n`;

        // Iniezione JSON-LD finale (blocco unico)
        const fullSchema = {
            ...result.schema_markup.article,
            "description": result.seo_metadata.meta_description,
            "mainEntity": {
                "@type": "FAQPage",
                "mainEntity": result.schema_markup.faq_schema
            }
        };
        const schemaScript = `\n\n<script type="application/ld+json">\n${JSON.stringify(fullSchema)}\n</script>`;

        result.htmlContent = fullHtml + schemaScript;
        result.groundingSources = extractSources(response);
        return result;
    } catch (error) {
        console.error(error);
        throw new Error("Errore durante l'ottimizzazione SEO AI.");
    }
};

