const slugify = (text: string) => text.toLowerCase().replace(/[^\w ]+/g, '').replace(/ +/g, '-').trim();

export const optimizeArticleForSeo = async (articleText: string): Promise<SeoResult> => {
    try {
        const prompt = `Agisci come Editor Tecnico Senior SEO per WordPress. Il tuo obiettivo è trasformare il testo fornito in codice HTML perfetto per l'AI Indexing.

REGOLE MANDATORIE "ZERO TOLERANCE":
1. **INTEGRITÀ DEL CONTENUTO**: NON accorciare mai il testo. Mantieni ogni paragrafo, dettaglio e spiegazione del testo originale. Non sintetizzare.
2. **NO INDICE (ToC)**: È ASSOLUTAMENTE VIETATO generare l'indice dei contenuti. Il plugin WordPress lo farà in automatico.
3. **STRUTTURA TITOLI & ANCORAGGI**: Un solo <h1>. Ogni <h2> e <h3> DEVE avere un attributo id unico e descrittivo (es: <h2 id="guida-tecnica-seo">).
4. **VINCOLO TECNICO DEFINITIVO SULLE TABELLE**:
   - NO NESTING: NON annidare mai tabelle dentro altre tabelle.
   - NO CONTAINER TABLE: NON usare mai <table> come box per racchiudere paragrafi o altro testo libero.
   - SOLO DATI: Se apri un tag <table>, deve contenere solo <thead>/<tbody>, <tr> e <th>/<td>.
   - TESTO FUORI: Ogni spiegazione o introduzione alla tabella deve stare in un tag <p> ESTERNAMENTE e SOPRA la tabella.
   - BOX STILIZZATI: Per box di testo, usa <div> con bordi, MAI tabelle.
5. **SNIPPET INIZIALE**: Primo paragrafo tra 40-80 parole, informativo e fluido.
6. **METADATI & SCHEMA**:
   - Meta Description all'inizio.
   - JSON-LD (TechArticle + FAQPage) alla fine, blocco unico senza commenti HTML.

Testo Sorgente:
${articleText}`;

        const response = await ai.models.generateContent({
            model: "gemini-3-flash-preview",
            contents: prompt,
            config: {
                responseMimeType: "application/json",
                responseSchema: responseSchema,
                tools: [{ googleSearch: {} }],
            },
        });

        const result: SeoResult = JSON.parse(response.text.trim());

        // Assemblaggio HTML Rigoroso
        let fullHtml = `<meta name="description" content="${result.seo_metadata.meta_description}">\n\n`;
        fullHtml += `<h1>${result.html_content.title}</h1>\n`;
        fullHtml += `<p>${result.html_content.intro}</p>\n\n`;

        result.html_content.sections.forEach(s => {
            const sId = slugify(s.heading);
            fullHtml += `<h2 id="${sId}">${s.heading}</h2>\n`;

            if (s.type === 'list') {
                fullHtml += `<ul>\n${s.content.split('\n').filter(l => l.trim()).map(li => `  <li>${li.replace(/^[*-]\s*/, '').trim()}</li>`).join('\n')}\n</ul>\n`;
            } else if (s.type === 'table') {
                // Pulizia table tag per sicurezza
                const cleanTableContent = s.content.replace(/<p>|<\/p>/g, '').trim();
                fullHtml += `<div style="overflow-x:auto; margin-bottom:25px;">\n<table border="1" style="width:100%; border-collapse:collapse;">\n${cleanTableContent}\n</table>\n</div>\n`;
            } else {
                fullHtml += `<p>${s.content}</p>\n`;
            }

            if (s.subsections) {
                s.subsections.forEach(sub => {
                    fullHtml += `<h3 id="${slugify(sub.heading)}">${sub.heading}</h3>\n`;
                    fullHtml += `<p>${sub.content}</p>\n`;
                });
            }
        });

        if (result.html_content.faq.length > 0) {
            fullHtml += `<h2 id="domande-frequenti-faq">Domande Frequenti (FAQ)</h2>\n`;
            result.html_content.faq.forEach(f => {
                const fId = slugify(f.question);
                fullHtml += `<div class="faq-item" style="margin-bottom:20px;">\n  <h3 id="${fId}">${f.question}</h3>\n  <p>${f.answer}</p>\n</div>\n`;
            });
        }

        fullHtml += `<p><strong>Conclusione:</strong> ${result.html_content.conclusion}</p>\n`;

        // JSON-LD Final Block
        const fullSchema = {
            ...result.schema_markup.article,
            "description": result.seo_metadata.meta_description,
            "mainEntity": {
                "@type": "FAQPage",
                "mainEntity": result.schema_markup.faq_schema
            }
        };
        const schemaScript = `\n\n<script type="application/ld+json">\n${JSON.stringify(fullSchema)}\n</script>`;

        result.htmlContent = fullHtml + schemaScript;
        result.groundingSources = extractSources(response);
        return result;
    } catch (error) {
        console.error(error);
        throw new Error("Errore durante l'ottimizzazione SEO AI.");
    }
};

