            }
        }
    },
    required: ["html_content", "schema_markup", "seo_metadata", "social_post", "seoChecklist", "readability"],
};

const slugify = (text: string) => text.toLowerCase().replace(/[^\w ]+/g, '').replace(/ +/g, '-').trim();

export const optimizeArticleForSeo = async (articleText: string): Promise<SeoResult> => {
    try {
        const prompt = `Agisci come Editor Tecnico Senior SEO per WordPress. Trasforma il testo fornito in codice HTML perfetto per l'AI Indexing.

REGOLE MANDATORIE "ZERO TOLERANCE":

1. INTEGRITÀ DEL CONTENUTO: 
   - NON accorciare mai il testo originale. 
   - Mantieni ogni paragrafo, ogni spiegazione e ogni dettaglio. 
   - È SEVERAMENTE VIETATO fare riassunti o sintesi. La lunghezza dell'output deve riflettere la ricchezza dell'input.

2. NO INDICE (ToC): 
   - È ASSOLUTAMENTE VIETATO generare l'indice dei contenuti (Table of Contents) o box liste all'inizio. 
   - Il plugin WordPress lo genererà automaticamente.

3. STRUTTURA TITOLI & ANCORAGGI: 
   - Un solo tag <h1>.
   - Ogni tag <h2> e <h3> DEVE avere un attributo 'id' univoco e descrittivo (es: <h2 id="titolo-sezione">).

4. VINCOLO TECNICO DEFINITIVO SULLE TABELLE (STOP ALLUCINAZIONI):
   - REGOLA D'ORO: Se il contenuto non è una lista di dati divisi in colonne, NON USARE <table>.
   - ESEMPIO DI ERRORE DA EVITARE (MAI FARE COSI): <table><p>Descrizione lunga...</p></table> (<- VIETATO!)
   - ESEMPIO CORRETTO (FAI SEMPRE COSI): <p style="border:1px solid #ddd; padding:10px;">Descrizione lunga...</p><table><tr><td>Dato</td><td>Dato</td></tr></table>
   - BOX STILIZZATI: Se devi mettere in risalto una frase o un'introduzione, usa esclusivamente un tag <div> o <p> con stili inline. MAI racchiudere una tabella dentro un'altra tabella o dentro un box table.
   - STRUTTURA PIATTA: Ogni tabella deve contenere solo <thead>/<tbody>, <tr>, <th>, <td>.

5. SNIPPET INIZIALE: 
   - Il primo paragrafo dopo l'H1 deve essere informativo e fluido (40-80 parole).

6. METADATI E SCHEMA:
   - Inserisci la Meta Description all'inizio.
   - Genera lo script JSON-LD (TechArticle + FAQPage) alla fine dell'articolo.

Testo Sorgente:
${articleText}`;

        const response = await ai.models.generateContent({
            model: "gemini-3-flash-preview",
            contents: prompt,
            config: {
                responseMimeType: "application/json",
                responseSchema: responseSchema,
                tools: [{ googleSearch: {} }],
            },
        });

        const result: SeoResult = JSON.parse(response.text.trim());

        let fullHtml = `<meta name="description" content="${result.seo_metadata.meta_description}">\n\n`;
        fullHtml += `<h1>${result.html_content.title}</h1>\n`;
        fullHtml += `<p>${result.html_content.intro}</p>\n\n`;

        result.html_content.sections.forEach(s => {
            const sId = slugify(s.heading);
            fullHtml += `<h2 id="${sId}">${s.heading}</h2>\n`;

            if (s.type === 'list') {
                fullHtml += `<ul>\n${s.content.split('\n').filter(l => l.trim()).map(li => `  <li>${li.replace(/^[*-]\s*/, '').trim()}</li>`).join('\n')}\n</ul>\n`;
            } else if (s.type === 'table') {
                // Sanificazione estrema
                const cleanTableContent = s.content.replace(/<p>|<\/p>/g, '').trim();
                fullHtml += `<div style="overflow-x:auto; margin-bottom:25px;">\n<table border="1" style="width:100%; border-collapse:collapse;">\n${cleanTableContent}\n</table>\n</div>\n`;
            } else {
                fullHtml += `<p>${s.content}</p>\n`;
            }

            if (s.subsections) {
                s.subsections.forEach(sub => {
                    fullHtml += `<h3 id="${slugify(sub.heading)}">${sub.heading}</h3>\n`;
                    fullHtml += `<p>${sub.content}</p>\n`;
                });
            }
        });

        if (result.html_content.faq.length > 0) {
            fullHtml += `<h2 id="domande-frequenti-faq-automatico">Domande Frequenti (FAQ)</h2>\n`;
            result.html_content.faq.forEach(f => {
                const fId = slugify(f.question);
                fullHtml += `<div class="faq-item" style="margin-bottom:20px; border-bottom:1px solid #eee; padding-bottom:15px;">\n  <h3 id="${fId}">${f.question}</h3>\n  <p>${f.answer}</p>\n</div>\n`;
            });
        }

        fullHtml += `<p><strong>Conclusione:</strong> ${result.html_content.conclusion}</p>\n`;

        const fullSchema = {
            ...result.schema_markup.article,
            "description": result.seo_metadata.meta_description,
            "mainEntity": {
                "@type": "FAQPage",
                "mainEntity": result.schema_markup.faq_schema
            }
        };
        const schemaScript = `\n\n<script type="application/ld+json">\n${JSON.stringify(fullSchema)}\n</script>`;

        result.htmlContent = fullHtml + schemaScript;
        result.groundingSources = extractSources(response);
        return result;
    } catch (error) {
        console.error(error);
        throw new Error("Errore durante l'ottimizzazione SEO AI.");
    }
};

export const enrichArticleDepth = async (currentResult: SeoResult, originalText: string): Promise<SeoResult> => {
    try {
        const prompt = `Arricchisci l'HTML fornito con link autorevoli senza rimuovere contenuti o modificare gli ID. 
        REGOLE: NON accorciare nulla. NO indici ToC. NO tabelle annidate. RISPETTA IL VINCOLO TECNICO SULLE TABELLE (SOLO DATI, NO BOX).
        Contenuto: ${currentResult.htmlContent}`;

        const response = await ai.models.generateContent({
            model: "gemini-3-flash-preview",
            contents: prompt,
            config: { tools: [{ googleSearch: {} }] },
        });

        return { ...currentResult, htmlContent: response.text || currentResult.htmlContent };
    } catch (error) {
        return currentResult;
    }
};

const extractSources = (response: any): GroundingSource[] => {
    const sources: GroundingSource[] = [];
    const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;
    if (chunks) {
        chunks.forEach((chunk: any) => {
            if (chunk.web?.uri) {
                sources.push({
                    title: chunk.web.title || "Fonte",
                    uri: chunk.web.uri
                });
            }
        });
    }
    return Array.from(new Map(sources.map(s => [s.uri, s])).values());
};

